/// Prepare the pipeline without serializing through WGSL. Unsupported stages still refuse.
pub fn prepare_module(program:&Program,pipeline:&Pipeline)->Result<PreparedModule,Error>{
    super::stage_supported(program)?;

// Ordinary modules still transport their inventory through the actual map.
precision = precision.unchanged_arithmetic(&pre_samplers,&module,crate::precision::TransformKind::ResourceBindings).map_err(Error::Pipeline)?;
let (compacted, receipt, _) = precision.compact(&module,naga::compact::KeepUnused::Yes).map_err(Error::Pipeline)?;
module = compacted; precision = receipt;

// the output's own value and the one its consumer reads it as, where they differ, and whether the consumer
// declares the output's input without reading any of its lanes
let (retyped, unread): (Vec<Option<(Value, Value)>>, Vec<bool>) = match pipeline.feeds {

// the retypes a consumer can observe: an input it declares but never reads still takes the output's location
// and type (WebGPU links a location only between values of one type), but no value it reads changes, so no note
let observed = || {
    retyped
        .iter()
        .zip(&unread)
        .filter(|(_, unread)| !**unread)
        .filter_map(|(retype, _)| retype.as_ref())
};
let padded = observed()

/// The rebuilt result structure's offsets and span. Members keep their offsets while they still fit: each starts at
/// or after the end of the one before, and the last ends within the span. A retype that makes a member larger than
/// the room before the next one (an output its consumer reads with more lanes, packed with the output after it)
/// would overlap it; then every member is laid out again, in order, at its type's alignment (WGSL's memory layout).
/// A result structure is not host-shareable, so its offsets only keep its members apart.
fn relayout(module: &naga::Module, members: &mut [StructMember], span: u32) -> Result<u32, Error> {
    let gctx = module.to_ctx();
    let mut end = 0u32;
    let mut fits = true;
    for m in members.iter() {
        fits &= m.offset >= end;
        end = m.offset.saturating_add(module.types[m.ty].inner.size(gctx));
    }
    if fits && end <= span {
        return Ok(span);
    }
    let mut layouter = naga::proc::Layouter::default();
    layouter
        .update(gctx)
        .map_err(|e| Error::Pipeline(format!("the result structure's layout: {e}")))?;
    let mut offset = 0u32;
    let mut alignment = naga::proc::Alignment::ONE;
    for m in members.iter_mut() {
        let layout = layouter[m.ty];
        m.offset = layout.alignment.round_up(offset);
        offset = m
            .offset
            .checked_add(layout.size)
            .ok_or_else(|| Error::Pipeline("the result structure's layout overflows".into()))?;
        alignment = alignment.max(layout.alignment);
    }
    Ok(alignment.round_up(offset))
}

