            .iter()
            .any(|r| Some(r.source_sha.as_str()) != source_sha)
        {
            return Err("PreciseSourceHashMismatch".into());
        }
        if self.is_precision_bearing()
            && self
                .module_identity
                .as_ref()
                .is_some_and(|id| *id != module_identity(module))
        {
            return Err("PreciseStaleModuleIdentity".into());
        }
        self.validate_coverage()?;
        self.validate_exact(module)?;
        self.validate_unary(module)?;
        for b in &self.bindings {
            let f = match &b.producer.owner {
                FunctionOwner::EntryPoint { index, name } => module
                    .entry_points
                    .get(*index)
                    .filter(|e| &e.name == name)
                    .map(|e| &e.function),
                FunctionOwner::Function(h) => module.functions.try_get(*h).ok(),
            }
            .ok_or("PreciseReceiptOwnerMismatch")?;
            let source = self
                .records
                .iter()
                .find(|r| r.word == b.source_word)
                .ok_or("PreciseSourceRecordMissing")?;
            if b.producer.module_revision != self.revision
                || b.operands.iter().any(|a| {
                    a.owner != b.producer.owner || a.module_revision != b.producer.module_revision
                })
            {
                return Err("PreciseReceiptRemapUnavailable: changed owner/revision".into());
            }
            let args: Vec<_> = b.operands.iter().map(|a| a.expression).collect();
            let e = f
                .expressions
                .try_get(b.producer.expression)
                .map_err(|_| "PreciseProducerMissing")?;
            let agrees = match e {
                _ if b.role == ProducerRole::SampleExplicitLod648 => check_sample648(self,module,f,b,source)?,
                _ if b.role == ProducerRole::RawLoad582 => check_raw_load582(self, module, f, b, source)?,
                _ if b.role == ProducerRole::RegisterCopy => check_register_copy(module, f, b, source)?,
                _ if matches!(b.role, ProducerRole::FracFloor | ProducerRole::FracSubtract) => {
                    source.instruction.name() == "frc" && check_frac(module, f, &self.bindings, b, source)?
                }
                _ if b.role == ProducerRole::SaturateAdd => {
                    source.instruction.name() == "add" && check_add_sat(module, f, b, source)?
                }
                _ if ToleranceOp::of_role(b.role).is_some() => {
                    matches!(source.instruction.name(), "sincos" | "rsq" | "div") && check_tolerance(module, f, b, source)?
                }
                _ if b.role == ProducerRole::MaxCompare => {
                    source.instruction.name() == "max" && check_max(module, f, b, source)?
                }
                _ if b.role == ProducerRole::ConditionalMove => {
                    source.instruction.name() == "movc" && check_conditional_move(module, f, b, source)?
                }
                _ if b.role == ProducerRole::CompareLess => {
                    source.instruction.name() == "lt" && check_less(module, f, b, source)?
                }
                _ if b.role == ProducerRole::RoundNi => {
                    source.instruction.name() == "round_ni" && check_round_ni(module, f, b, source)?
                }
                Expression::Binary { op: naga::BinaryOperator::ShiftLeft, left, right }
                    if b.role == ProducerRole::LogicalShift => {
                        args == [*left, *right] && check_logical_shift(f, b, source)?
                    },
                Expression::Math {
                    fun: naga::MathFunction::Exp2,
                    arg,
                    arg1: None,
                    arg2: None,
                    arg3: None,
                } => args == [*arg] && source.instruction.name() == "exp",
                Expression::Binary { op, left, right }
                    if matches!(
                        source.instruction.name(),
                        "add" | "mul" | "iadd" | "imul" | "umul"
                    ) =>
                {
                    args == [*left, *right]
                        && *op
                            == if matches!(source.instruction.name(), "add" | "iadd") {
                                naga::BinaryOperator::Add
                            } else {
                                naga::BinaryOperator::Multiply
                            }
                        && check_source_modifiers(module, f, b, source)?
                }
                Expression::Math {
                    fun: naga::MathFunction::Dot,
                    arg,
                    arg1: Some(right),
                    ..
                } => {
                    args == [*arg, *right]
                        && source.instruction.name().starts_with("dp")
                        && check_source_modifiers(module, f, b, source)?
                }
                _ => false,
            };
            check_binding_type(module, f, b)?;
            if !agrees || f.expression_controls.get(&b.producer.expression).copied() != b.control()
            {
                return Err("PreciseProducerMismatch".into());
            }
        }
        for (index, e) in module.entry_points.iter().enumerate() {
            let owner = FunctionOwner::EntryPoint {
                index,
                name: e.name.clone(),
            };
            for h in e.function.expression_controls.keys() {
                if !self.bindings.iter().any(|b| {
                    b.controlled && b.producer.owner == owner && b.producer.expression == *h
                }) {
                    return Err("PreciseControlWithoutReceipt".into());
                }
            }
        }
        for (h, f) in module.functions.iter() {
            for e in f.expression_controls.keys() {
                if !self.bindings.iter().any(|b| {
                    b.controlled
                        && b.producer.owner == FunctionOwner::Function(h)
                        && b.producer.expression == *e
                }) {
                    return Err("PreciseControlWithoutReceipt".into());
                }
            }
        }
        Ok(())
    }
}

