#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ExactLane {
    pub destination: u8,
    pub selected_source: u8,
    pub bits: u32,
    pub marked: bool,
}
/// Checked ordinary-temp immediate domain; all written lanes are retained, including unmarked lanes.
pub fn exact_immediate_lanes(r: &SourceInstruction) -> Result<Vec<ExactLane>, String> {
    let i = &r.instruction;
    let mut tokens = vec![0x50050, (r.words.len() + 2) as u32];
    tokens.extend_from_slice(&r.words);
    let decoded = dxbc_reader::decode::decode(&tokens).map_err(|_| "ExactMoveRawDecodeMismatch")?;
    if decoded.instructions.len() != 1 {
        return Err("ExactMoveRawDecodeMismatch".into());
    }
    let mut actual = decoded.instructions[0].clone();
    actual.word = i.word;
    if format!("{actual:?}") != format!("{i:?}") {
        return Err("ExactMoveRawDecodeMismatch".into());
    }
    if r.flags.len() != 1 || r.flags[0] & 1 == 0 {
        return Err("ExactMoveSourcePolicyMismatch".into());
    }

    if i.name() != "mov" || i.operands.len() != 2 || i.precise_mask() == 0 {
        return Err("ExactMoveOpcodeUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| o.modifier != 0 || o.non_uniform)
    {
        return Err("ExactMoveModifierUnsupported".into());
    }
    if i.operands.iter().any(|o| o.precision != 0) {
        return Err("ExactMoveMinimumPrecisionUnsupported".into());
    }
    let d = &i.operands[0];
    let s = &i.operands[1];
    if d.register != Register::Temp
        || d.indices.len() != 1
        || d.indices[0].relative.is_some()
        || s.register != Register::Immediate
        || !s.indices.is_empty()
    {
        return Err("ExactMoveOperandDomainUnsupported".into());
    }
    let Selection::Mask(mask) = d.selection else {
        return Err("ExactMoveDestinationUnsupported".into());
    };
    if mask == 0 || mask & !15 != 0 || i.precise_mask() & !mask != 0 {
        return Err("ExactMoveMaskUnsupported".into());
    }
    let expected_lanes = (0..4u8)
        .filter(|l| mask & (1 << l) != 0)
        .collect::<Vec<_>>();
    if r.reason != PrecisionReason::ExplicitMask
        || r.destinations.len() != 1
        || r.destinations[0].ordinal != 0
        || r.destinations[0].null
        || r.destinations[0].mask != mask
        || r.destinations[0].lanes != expected_lanes
    {
        return Err("ExactMoveDestinationInventoryMismatch".into());
    }
    let mut lanes = vec![];
    for destination in 0..4u8 {
        if mask & (1 << destination) != 0 {
            let selected_source = match s.selection {
                Selection::Mask(_) => destination,
                Selection::Scalar(c) => c,
                Selection::Swizzle(sw) => sw[destination as usize],
                Selection::None => return Err("ExactMoveSelectionUnsupported".into()),
            };
            let bits = *s
                .immediate
                .get(selected_source as usize)
                .ok_or("ExactMoveSelectionUnsupported")?;
            // A DXBC immediate mov is a raw 32-bit copy (D3D11 float rules: data movement
            // does not manipulate the data). The lifter stores u32 literal bits, so +0/-0,
            // denormals, INF and NaN payloads are carried bit-exactly; consumers keep their own
            // source semantics. No exponent class is refused here any more.
            lanes.push(ExactLane {
                destination,
                selected_source,
                bits,
                marked: i.precise_mask() & (1 << destination) != 0,
            });
        }
    }
    Ok(lanes)
}
