                    let uses = self
                        .exact_proofs
                        .iter()
                        .flat_map(|p| &p.analysis.uses)
                        .filter(|u| u.atom.origin == Some((mov.source_word, l.destination)))
                        .count();
                    if uses == 0 {
                        ExactLaneDisposition::DeadPureCopy {
                            destination: l.destination,
                        }
                    } else {
                        ExactLaneDisposition::ArithmeticUses {
                            destination: l.destination,
                            uses,
                        }
                    }
                })
                .collect();
        }
        Ok(())
    }
}

#[derive(Clone, Debug)]
pub struct DeadExactUse {
    pub owner: FunctionOwner,
    pub usage: exact_eval::Use,
    pub removed_at_revision: u32,
    pub pre_module: String,
}

/// DeadPureCopy is a proof of no escaping/observed arithmetic use, not a claim that a store was removed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ExactLaneDisposition {
    ArithmeticUses { destination: u8, uses: usize },
    DeadPureCopy { destination: u8 },
}

// Shared algorithm compiled against each package's actual IR types. No arithmetic evaluation.
use naga::{Expression as E, Handle, Literal, Statement as S};
use std::collections::BTreeMap;
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Atom {
    pub bits: Option<u32>,
    pub opaque: Option<Handle<E>>,
    pub origin: Option<(usize, u8)>,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Seed {
    pub pointer: Handle<E>,
    pub value: Handle<E>,
    pub lanes: Vec<(u8, u32, usize, u8)>, // packed lane, bits, source word, destination lane
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Use {
    pub producer: Handle<E>,
    pub operand: Handle<E>,
    pub ordinal: usize,
    pub lane: u8,
    pub atom: Atom,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Assignment {
    pub statement: usize,
    pub pointer: Handle<E>,
    pub value: Handle<E>,
    pub local: usize,
    pub first_lane: usize,
    pub values: Vec<Option<Atom>>,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Analysis {
    pub values: BTreeMap<usize, Vec<Option<Atom>>>,
    pub uses: Vec<Use>,
    pub assignments: Vec<Assignment>,
    pub overwrites: Vec<(usize, usize, u8)>, // statement/source word/destination lane
}
fn tagged(v: &[Option<Atom>]) -> bool {
    v.iter()
        .flatten()
        .any(|a| a.origin.is_some() || a.opaque.is_some())
}
// Ephemeral checked boundary. No caller-constructible or serialized facts.
// The module is borrowed immutably through verification and analysis, so facts
// cannot survive a mutation, compaction or owner remap.
#[derive(Default)]
struct Interface {
    samples648: std::collections::BTreeSet<usize>,
    raw_words582: std::collections::BTreeSet<usize>,
    inputs: std::collections::BTreeSet<usize>,
    outputs: std::collections::BTreeSet<usize>,
}
fn interface(m: &naga::Module, owner: naga::correspondence::Owner) -> Result<Interface, String> {
    use naga::{TypeInner as T, AddressSpace as A};
    let fail = || "ImportedInterfaceStructureUnsupported".to_string();
    if m.entry_points.len() != 1 || m.functions.len() != 1 { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let naga::correspondence::Owner::Function(selected) = owner else { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); };
    let (actual, f) = m.functions.iter().next().ok_or_else(fail)?;
    if selected != actual || !f.arguments.is_empty() || f.result.is_some() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let w = &m.entry_points[0].function;
    if !w.local_variables.is_empty() || !w.expression_controls.is_empty() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let cell = |g: naga::Handle<naga::GlobalVariable>| -> Result<(), String> {
        let v = &m.global_variables[g];
        if v.space != A::Private || v.binding.is_some() || !v.memory_decorations.is_empty() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
        match m.types[v.ty].inner {
            T::Scalar(s) | T::Vector { scalar: s, .. }
                if s.width == 4 && matches!(s.kind, naga::ScalarKind::Float | naga::ScalarKind::Sint | naga::ScalarKind::Uint) => Ok(()),
            _ => Err(fail()),
        }
    };
    let mut facts = Interface::default();
    let mut used = std::collections::BTreeSet::new();
    let mut body = w.body.iter();
    for (i, arg) in w.arguments.iter().enumerate() {
        let Some(S::Store { pointer, value }) = body.next() else { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); };
        let E::GlobalVariable(g) = w.expressions[*pointer] else { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); };
        if !matches!(w.expressions[*value], E::FunctionArgument(k) if k as usize == i)
            || arg.binding.is_none() || arg.ty != m.global_variables[g].ty
            || !facts.inputs.insert(g.index()) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
        cell(g)?; used.insert(pointer.index()); used.insert(value.index());
    }
    if !matches!(body.next(), Some(S::Call { function, arguments, result: None }) if *function == selected && arguments.is_empty()) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let mut emitted = std::collections::BTreeSet::new();
    let returned = loop {
        match body.next() {
            Some(S::Emit(range)) => for h in range.clone() {
                if !emitted.insert(h.index()) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
                match &w.expressions[h] {
                    E::Load { pointer } => {
                        let E::GlobalVariable(g) = w.expressions[*pointer] else { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); };
                        cell(g)?;
                        if facts.inputs.contains(&g.index()) || !facts.outputs.insert(g.index()) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
                        used.insert(pointer.index());
                    }
                    E::Compose { components, .. } if components.iter().all(|h| emitted.contains(&h.index()) && matches!(w.expressions[*h], E::Load { .. })) => {},
                    _ => return Err(fail()),
                }
                used.insert(h.index());
            },
            Some(S::Return { value }) => break *value,
            None if w.result.is_none() && emitted.is_empty() => break None,
            _ => return Err(fail()),
        }
    };
    if body.next().is_some() || used.len() != w.expressions.len() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let output_count = match (returned, &w.result) {
        (Some(h), Some(_)) if emitted.contains(&h.index()) => match &w.expressions[h] {
            E::Load { .. } => 1,
            E::Compose { components, .. } => {
                let unique: std::collections::BTreeSet<_> = components.iter().collect();
                if unique.len() != components.len() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
                components.len()
            },
            _ => return Err(fail()),
        },
        (None, None) => 0,
        _ => return Err(fail()),
    };
    if output_count != facts.outputs.len() { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    // No other functions/entries can write these cells. The selected callee
    // is a single straight-line invocation, without early returns or effects.
    fn statements<'a>(b: &'a naga::Block, out: &mut Vec<&'a S>) {
        for s in b.iter() { if let S::Block(b) = s { statements(b, out); } else { out.push(s); } }
    }
    let mut ss = vec![]; statements(&f.body, &mut ss);
    if !matches!(ss.pop(), Some(S::Return { value: None })) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    let mut writes = std::collections::BTreeSet::new();
    for s in ss {
        match s {
            S::Emit(_) => {},
            S::Store { pointer, .. } => if let E::GlobalVariable(g) = f.expressions[*pointer] {
                if !facts.outputs.contains(&g.index()) { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
                writes.insert(g.index());
            },
            _ => return Err(fail()),
        }
    }
    if writes != facts.outputs { return Err(format!("ImportedInterfaceStructureUnsupported:{}", line!())); }
    Ok(facts)
}
/// Analyze the actual imported owner under a freshly verified parser boundary.
/// Ordinary analyze/analyze_opaque never opt into this contract.
pub fn analyze_imported(
    m: &naga::Module, owner: naga::correspondence::Owner,
    seeds: &[Seed], opaque: &[Handle<E>],
) -> Result<Analysis, String> {
    analyze_imported_raw582(m,owner,seeds,opaque,&[])
}
/// Additional immutable raw-word roots, supplied only after checked source/SPIR-V provenance.
pub fn analyze_imported_raw582(m:&naga::Module,owner:naga::correspondence::Owner,seeds:&[Seed],opaque:&[Handle<E>],roots:&[Handle<naga::GlobalVariable>])->Result<Analysis,String>{
    analyze_imported_sampled648(m,owner,seeds,opaque,roots,&[])
}
/// Sample handles originate only from the checked execution-local sample/result report join.
pub fn analyze_imported_sampled648(m:&naga::Module,owner:naga::correspondence::Owner,seeds:&[Seed],opaque:&[Handle<E>],roots:&[Handle<naga::GlobalVariable>],samples:&[Handle<E>])->Result<Analysis,String>{
    // Naga requires acyclic, topologically ordered function handles before
    // validation. Reject malformed call graphs rather than letting the validator
    // index an unavailable callee summary. This grants no call permission.
    fn calls(b: &naga::Block, limit: usize) -> Result<(), String> {
        for s in b.iter() { match s {
            S::Call { function, .. } if function.index() >= limit => return Err("ImportedInterfaceCallGraphUnsupported".into()),
            S::Block(b) => calls(b, limit)?,
            S::If { accept, reject, .. } => { calls(accept, limit)?; calls(reject, limit)?; },
            S::Switch { cases, .. } => for c in cases { calls(&c.body, limit)?; },
            S::Loop { body, continuing, .. } => { calls(body, limit)?; calls(continuing, limit)?; },
            _ => {},
        }} Ok(())
    }
    for (h, f) in m.functions.iter() { calls(&f.body, h.index())?; }
    for e in &m.entry_points { calls(&e.function.body, m.functions.len())?; }
    naga::valid::Validator::new(naga::valid::ValidationFlags::all(), naga::valid::Capabilities::all())
        .validate(m).map_err(|e| format!("ImportedInterfaceInvalid: {e:?}"))?;
    let f = match owner {
        naga::correspondence::Owner::Function(h) => m.functions.try_get(h).map_err(|_| "ImportedInterfaceOwnerMissing")?,
        naga::correspondence::Owner::EntryPoint(i) => &m.entry_points.get(i).ok_or("ImportedInterfaceOwnerMissing")?.function,
    };
    if matches!(owner, naga::correspondence::Owner::EntryPoint(0)) && m.entry_points.len() == 1 && m.functions.is_empty() {
        return analyze_sampled648(m, f, seeds, opaque, roots,samples);
    }
    // Pure owners retain their ordinary analysis; no memory fact is needed.
    if let Ok(analysis) = analyze_sampled648(m, f, seeds, opaque, roots,samples) { return Ok(analysis); }
    let mut facts = interface(m, owner)?;
    raw_roots582(m,roots,&mut facts)?;
    for &h in samples{sample_shape648(m,f,h)?;if !facts.samples648.insert(h.index()){return Err("Sample648AmbiguousFact".into())}}
    analyze_with_interface(m, f, seeds, opaque, Some(&facts))
}

fn raw_word_type582(m:&naga::Module,ty:&naga::TypeInner)->bool{
    use naga::TypeInner as T;
    match ty {
        T::Array{base,size:naga::ArraySize::Dynamic,stride:4}=>m.types[*base].inner==T::Scalar(naga::Scalar::U32),
        T::Struct{members,span:4} if members.len()==1 && members[0].offset==0 && members[0].binding.is_none()=>matches!(m.types[members[0].ty].inner,T::Array{size:naga::ArraySize::Dynamic,stride:4,..}) && raw_word_type582(m,&m.types[members[0].ty].inner),
        _=>false,
    }
}
fn raw_roots582(m:&naga::Module,roots:&[Handle<naga::GlobalVariable>],facts:&mut Interface)->Result<(),String>{
    for &g in roots {
        let v=m.global_variables.try_get(g).map_err(|_|"Raw582AnalysisRootMissing")?;
        if v.space!=(naga::AddressSpace::Storage{access:naga::StorageAccess::LOAD}) || v.binding.is_none() || !raw_word_type582(m,&m.types[v.ty].inner) || !facts.raw_words582.insert(g.index()) {return Err("Raw582AnalysisRootTypeOrAccess".into())}
    }Ok(())
}
/// A root is an immutable uint32 word array; addresses still pass edge tracking and tagged addresses refuse.
pub fn analyze_raw_words582(m:&naga::Module,f:&naga::Function,seeds:&[Seed],opaque:&[Handle<E>],roots:&[Handle<naga::GlobalVariable>])->Result<Analysis,String>{
    if roots.is_empty(){return analyze_opaque(m,f,seeds,opaque)}
    let mut facts=Interface::default();raw_roots582(m,roots,&mut facts)?;analyze_with_interface(m,f,seeds,opaque,Some(&facts))
}
/// Called only after source-bound sample receipt validation. Ordinary analysis remains closed.
pub fn analyze_sampled648(m:&naga::Module,f:&naga::Function,seeds:&[Seed],opaque:&[Handle<E>],roots:&[Handle<naga::GlobalVariable>],samples:&[Handle<E>])->Result<Analysis,String>{
 if samples.is_empty(){return analyze_raw_words582(m,f,seeds,opaque,roots)}
 let mut facts=Interface::default();raw_roots582(m,roots,&mut facts)?;
 for &h in samples{sample_shape648(m,f,h)?;if !facts.samples648.insert(h.index()){return Err("Sample648AmbiguousFact".into())}}
 analyze_with_interface(m,f,seeds,opaque,Some(&facts))
}
pub fn sample_shape648(m:&naga::Module,f:&naga::Function,result:Handle<E>)->Result<(Handle<E>,Handle<E>,Handle<E>),String>{
 let fail=||"Sample648ShapeOrResourceUnsupported".to_string();
 let E::AccessIndex{base:sample,index:0}=f.expressions[result]else{return Err(fail())};
 let E::ImageSample{image,sampler,gather:None,coordinate,array_index:None,offset:None,level:naga::SampleLevel::Exact(lod),depth_ref:None,clamp_to_edge:false}=f.expressions[sample]else{return Err(fail())};
 let positive_zero=match f.expressions[lod]{E::Literal(Literal::F32(x))=>x.to_bits()==0,E::Constant(c)=>matches!(m.global_expressions[m.constants[c].init],E::Literal(Literal::F32(x))if x.to_bits()==0),_=>false};if !positive_zero{return Err(fail())}
 let E::GlobalVariable(ig)=f.expressions[image]else{return Err(fail())};let E::GlobalVariable(sg)=f.expressions[sampler]else{return Err(fail())};
 let i=&m.global_variables[ig];let s=&m.global_variables[sg];
 if i.space!=naga::AddressSpace::Handle||s.space!=naga::AddressSpace::Handle||m.types[i.ty].inner!= (naga::TypeInner::Image{dim:naga::ImageDimension::D2,arrayed:false,class:naga::ImageClass::Sampled{kind:naga::ScalarKind::Float,multi:false}})||m.types[s.ty].inner!=(naga::TypeInner::Sampler{comparison:false}){return Err(fail())}
 Ok((sample,coordinate,lod))
}
pub fn analyze(m: &naga::Module, f: &naga::Function, seeds: &[Seed]) -> Result<Analysis, String> {
    analyze_opaque(m, f, seeds, &[])
}
pub fn analyze_opaque(
    m: &naga::Module,
    f: &naga::Function,
    seeds: &[Seed],
    opaque: &[Handle<E>],
) -> Result<Analysis, String> {
    analyze_with_interface(m, f, seeds, opaque, None)
}
fn analyze_with_interface(m: &naga::Module, f: &naga::Function, seeds: &[Seed], opaque: &[Handle<E>], interface: Option<&Interface>) -> Result<Analysis, String> {
    let mut t = naga::front::Typifier::new();
    let ctx = naga::proc::ResolveContext::with_locals(m, &f.local_variables, &f.arguments);
    let mut widths = BTreeMap::new();
    let mut types = BTreeMap::new();
    for (h, _) in f.expressions.iter() {
        t.grow(h, &f.expressions, &ctx).map_err(|e| e.to_string())?;
        let n = match t.get(h, &m.types) {
            naga::TypeInner::Scalar(s) if s.width == 4 => 1,
            naga::TypeInner::Vector { size, scalar } if scalar.width == 4 => *size as usize,
            _ => 0,
        };
        widths.insert(h.index(), n);
        types.insert(h.index(), t.get(h, &m.types).clone());
    }
    struct Run<'a> {
        m: &'a naga::Module,
        interface: Option<&'a Interface>,
        f: &'a naga::Function,
        seeds: &'a [Seed],
        opaque: &'a [Handle<E>],
        widths: BTreeMap<usize, usize>,
        types: BTreeMap<usize, naga::TypeInner>,
        uniform: BTreeMap<usize, usize>,
        clean_aggregate: std::collections::BTreeSet<usize>,
        locals: BTreeMap<usize, Vec<Option<Atom>>>,
        outputs: BTreeMap<usize, Vec<Option<Atom>>>,
        out: Analysis,
        used: Vec<usize>,
        statement: usize,
    }
    impl Run<'_> {
        fn index(&self, h: Handle<E>) -> Option<usize> {
            match self.f.expressions[h] {
                E::Literal(Literal::U32(v)) => Some(v as usize),
                E::Literal(Literal::I32(v)) if v >= 0 => Some(v as usize),
                E::Constant(c) => match self.m.global_expressions[self.m.constants[c].init] {
                    E::Literal(Literal::U32(v)) => Some(v as usize),
                    E::Literal(Literal::I32(v)) if v >= 0 => Some(v as usize),
                    _ => None,
                },
                _ => None,
            }
        }
        fn pointer(&self, h: Handle<E>) -> Option<(usize, usize)> {
            match self.f.expressions[h] {
                E::LocalVariable(l) => Some((l.index(), 0)),
                E::Access { base, index } => match self.f.expressions[base] {
                    E::LocalVariable(l) => Some((l.index(), self.index(index)?)),
                    _ => None,
                },
                E::AccessIndex { base, index } => match self.f.expressions[base] {
                    E::LocalVariable(l) => Some((l.index(), index as usize)),
                    _ => None,
                },
                _ => None,
            }
        }
        // Certified outputs have distinct cells with definite reaching writes.
        // Only direct scalar/vector cells and fixed lanes are modeled; no
        // aliases, nested pointers, or mutable dynamic selection are accepted.
        fn output_pointer(&self, h: Handle<E>) -> Option<(usize, usize)> {
            let (root, lane) = match self.f.expressions[h] {
                E::GlobalVariable(_) => (h, 0),
                E::AccessIndex { base, index } => (base, index as usize),
                E::Access { base, index } => (base, self.index(index)?),
                _ => return None,
            };
            match self.f.expressions[root] {
                E::GlobalVariable(g) if self.interface.is_some_and(|i| i.outputs.contains(&g.index())) => Some((g.index(), lane)),
                _ => None,
            }
        }
        // These facts are analysis-only and are established at Emit, never by
        // re-evaluating a local index when a later Load uses the address.
        fn memory_type(&self, ty: &naga::TypeInner, depth: usize) -> bool {
            use naga::TypeInner as T;
            if depth > 64 { return false; }
            match ty {
                T::Scalar(s) | T::Vector { scalar: s, .. } | T::Matrix { scalar: s, .. } =>
                    s.width == 4 && matches!(s.kind, naga::ScalarKind::Float | naga::ScalarKind::Sint | naga::ScalarKind::Uint),
                T::Array { size: naga::ArraySize::Dynamic, .. } if self.interface.is_some_and(|i|!i.raw_words582.is_empty()) => raw_word_type582(self.m,ty),
                T::Array { base, size: naga::ArraySize::Constant(_), .. } =>
                    self.memory_type(&self.m.types[*base].inner, depth + 1),
                T::Struct { members, .. } => members.iter().all(|v| self.memory_type(&self.m.types[v.ty].inner, depth + 1)),
                _ => false,
            }
        }
        fn pointee(&self, h: Handle<E>) -> Option<naga::TypeInner> {
            use naga::TypeInner as T;
            match &self.types[&h.index()] {
                T::Pointer { base, space: naga::AddressSpace::Storage{access:naga::StorageAccess::LOAD} } if self.interface.is_some_and(|i|!i.raw_words582.is_empty()) => Some(self.m.types[*base].inner.clone()),
                T::Pointer { base, space: naga::AddressSpace::Uniform } => Some(self.m.types[*base].inner.clone()),
                T::ValuePointer { size, scalar, space: naga::AddressSpace::Uniform } => Some(match size {
                    Some(size) => T::Vector { size: *size, scalar: *scalar },
                    None => T::Scalar(*scalar),
                }),
                _ => None,
            }
        }
        fn element(&self, ty: &naga::TypeInner, index: Option<u32>) -> Result<naga::TypeInner, String> {
            use naga::TypeInner as T;
            let in_range = |len: u32| index.is_none_or(|i| i < len);
            Ok(match ty {
                T::Array { base, size:naga::ArraySize::Dynamic,.. } if self.interface.is_some_and(|i|!i.raw_words582.is_empty()) && raw_word_type582(self.m,ty) => self.m.types[*base].inner.clone(),
                T::Array { base, size: naga::ArraySize::Constant(len), .. } if in_range(len.get()) => self.m.types[*base].inner.clone(),
                T::Vector { size, scalar } if in_range(*size as u32) => T::Scalar(*scalar),
                T::Matrix { columns, rows, scalar } if in_range(*columns as u32) => T::Vector { size: *rows, scalar: *scalar },
                T::Struct { members, .. } => self.m.types[members.get(index.ok_or("ExactMoveDynamicStructUnsupported")? as usize).ok_or("ExactMoveAccessShapeUnsupported")?.ty].inner.clone(),
                _ => return Err("ExactMoveAccessShapeUnsupported".into()),
            })
        }
        fn access(&mut self, h: Handle<E>, base: Handle<E>, fixed: Option<u32>, dynamic: Option<Handle<E>>) -> Result<Vec<Option<Atom>>, String> {
            self.val(base)?;
            if let Some(index) = dynamic {
                // Address selection is an observable use, not a copy of the
                // selected data. The single-origin representation cannot carry
                // tracked address dependencies: refuse them explicitly.
                self.edge(h, &[index], false)?;
                if !matches!(self.types[&index.index()], naga::TypeInner::Scalar(naga::Scalar { kind: naga::ScalarKind::Uint | naga::ScalarKind::Sint, width: 4 })) {
                    return Err("ExactMoveIndexTypeUnsupported".into());
                }
            }
            let n = self.widths[&h.index()];
            if let Some(root) = self.uniform.get(&base.index()).copied() {
                let ty = self.pointee(base).ok_or("ExactMoveUniformPointerTypeUnsupported")?;
                let element = self.element(&ty, fixed)?;
                if self.pointee(h).as_ref() != Some(&element) {
                    return Err("ExactMoveUniformPointerTypeUnsupported".into());
                }
                self.uniform.insert(h.index(), root);
                return Ok(vec![]);
            }
            if matches!(self.types[&base.index()], naga::TypeInner::Pointer { .. } | naga::TypeInner::ValuePointer { .. }) {
                // Keep the existing exact scalar/vector local slots. Dynamic,
                // nested and aliased mutable addresses have no memory model here.
                if self.pointer(h).is_none() && self.output_pointer(h).is_none() { return Err("ExactMoveAddressRootUnsupported".into()); }
                return Ok(vec![]);
            }
            let element = self.element(&self.types[&base.index()], fixed)?;
            if element != self.types[&h.index()] { return Err("ExactMoveAccessShapeUnsupported".into()); }
            if self.clean_aggregate.contains(&base.index()) {
                if n == 0 { self.clean_aggregate.insert(h.index()); }
                return Ok(vec![None; n]);
            }
            let v = self.val(base)?;
            if !matches!(self.types[&base.index()], naga::TypeInner::Vector { .. }) {
                return Err("ExactMoveAggregateAccessUnsupported".into());
            }
            if let Some(k) = fixed.map(|v| v as usize).or_else(|| dynamic.and_then(|i| self.index(i))) {
                return Ok(vec![v.get(k).cloned().ok_or("ExactMoveAccessShapeUnsupported")?]);
            }
            if tagged(&v) { return Err("ExactMoveDynamicValueAccessUnsupported".into()); }
            Ok(vec![None; n])
        }

        fn val(&mut self, h: Handle<E>) -> Result<Vec<Option<Atom>>, String> {
            if let Some(v) = self.out.values.get(&h.index()) {
                return Ok(v.clone());
            }
            // Loads and computed values must have been encountered in their actual Emit statement.
            if !self.f.expressions[h].needs_pre_emit() {
                return Err("ExactMoveUseBeforeEmitUnsupported".into());
            }
            self.eval(h)
        }
        fn eval(&mut self, h: Handle<E>) -> Result<Vec<Option<Atom>>, String> {
            let n = self.widths[&h.index()];
            let unknown = vec![None; n];
            let atom = |bits| {
                vec![Some(Atom {
                    bits: Some(bits),
                    origin: None,
                    opaque: None,
                })]
            };
            let v = match self.f.expressions[h].clone() {
                E::Literal(Literal::U32(v)) => atom(v),
                E::Literal(Literal::I32(v)) => atom(v as u32),
                E::Literal(Literal::F32(v)) => atom(v.to_bits()),
                E::Literal(_)
                | E::FunctionArgument(_)
                | E::LocalVariable(_) => unknown,
                E::GlobalVariable(g) => {
                    let var = &self.m.global_variables[g];
                    if var.space == naga::AddressSpace::Uniform || self.interface.is_some_and(|i|i.raw_words582.contains(&g.index())) {
                        let ty = &self.m.types[var.ty].inner;
                        if !self.memory_type(ty, 0) || self.pointee(h).as_ref() != Some(ty) {
                            return Err("ExactMoveUniformRootTypeUnsupported".into());
                        }
                        self.uniform.insert(h.index(), g.index());
                    }
                    unknown
                },
                E::ArrayLength(pointer) => {
                    self.val(pointer)?;
                    if !self.interface.is_some_and(|i|self.uniform.get(&pointer.index()).is_some_and(|g|i.raw_words582.contains(g))) {return Err("Raw582ArrayLengthProvenanceUnsupported".into())}
                    if n!=1 || self.types[&h.index()]!=naga::TypeInner::Scalar(naga::Scalar::U32)
                        || !self.pointee(pointer).is_some_and(|t|matches!(t,naga::TypeInner::Array{size:naga::ArraySize::Dynamic,stride:4,..}) && raw_word_type582(self.m,&t)) {return Err("Raw582ArrayLengthType".into())}
                    unknown
                },
                E::Constant(c) => global(self.m, self.m.constants[c].init, 0)?,
                E::ZeroValue(_) => vec![
                    Some(Atom {
                        bits: Some(0),
                        opaque: None,
                        origin: None
                    });
                    n
                ],
                E::Load { pointer } => {
                    self.val(pointer)?;
                    if let Some((l, k)) = self.pointer(pointer) {
                        let v = self.locals.get(&l).ok_or("ExactMoveLocalMissing")?;
                        v.get(k..k + n)
                            .ok_or("ExactMoveLoadLaneUnsupported")?
                            .to_vec()
                    } else if let Some((g, k)) = self.output_pointer(pointer) {
                        self.outputs.get(&g).ok_or("ExactMoveOutputReadBeforeWrite")?
                            .get(k..k+n).ok_or("ExactMoveOutputLaneUnsupported")?.to_vec()
                    } else if matches!(self.f.expressions[pointer], E::GlobalVariable(g) if self.interface.is_some_and(|i| i.inputs.contains(&g.index()))) {
                        // Direct immutable input cell, initialized by the checked
                        // wrapper argument store. Validator proves exact load type.
                        unknown
                    } else if self.uniform.contains_key(&pointer.index()) {
                        let ty = self.pointee(pointer).ok_or("ExactMoveUniformPointerTypeUnsupported")?;
                        if ty != self.types[&h.index()] || !self.memory_type(&ty, 0) {
                            return Err("ExactMoveUniformLoadTypeUnsupported".into());
                        }
                        // Uniform data cannot contain shader MOV/EXP atoms and
                        // cannot alias shader-writable storage. All address
                        // dependencies were already observed at their Emits.
                        if n == 0 { self.clean_aggregate.insert(h.index()); }
                        unknown
                    } else {
                        return Err("ExactMoveLoadRootUnsupported".into());
                    }
                }
                E::Access { base, index } => self.access(h, base, None, Some(index))?,
                E::AccessIndex { base, index } => {let v=self.access(h, base, Some(index), None)?;
                    if self.opaque.contains(&h)&&self.interface.is_some_and(|i|i.samples648.contains(&h.index())){
                        if n!=1{return Err("Sample648ResultWidth".into())}vec![Some(Atom{bits:None,origin:None,opaque:Some(h)})]
                    }else{v}
                },
                E::ImageSample{image,sampler,coordinate,level:naga::SampleLevel::Exact(lod),..}=>{
                    let permitted=self.interface.is_some_and(|i|i.samples648.iter().any(|k|self.f.expressions.iter().any(|(r,_)|r.index()==*k&&matches!(self.f.expressions[r],E::AccessIndex{base,index:0}if base==h))));
                    if !permitted{return Err("Sample648UncheckedRead".into())}
                    self.edge(h,&[image,sampler,coordinate,lod],false)?;unknown
                },
                E::Compose { components, .. } => {
                    let mut v = vec![];
                    let clean = self.interface.is_some() && self.memory_type(&self.types[&h.index()], 0) && components.iter().all(|c|
                        self.memory_type(&self.types[&c.index()], 0) && (self.widths[&c.index()] != 0 || self.clean_aggregate.contains(&c.index())));
                    for c in components {
                        v.extend(self.val(c)?)
                    }
                    if n == 0 {
                        if tagged(&v) {
                            return Err("ExactMoveAggregateEscapeUnsupported".into());
                        }
                        // Imported output structs are data only; pointer/unknown
                        // aggregates do not gain this fact. Tagged lanes refused above.
                        if clean { self.clean_aggregate.insert(h.index()); }
                        unknown
                    } else {
                        if v.len() != n {
                            return Err("ExactMoveCompositeWidthUnsupported".into());
                        }
                        v
                    }
                }
                E::Splat { value, .. } => vec![self.val(value)?.first().cloned().flatten(); n],
                E::Swizzle {
                    vector, pattern, ..
                } => {
                    let v = self.val(vector)?;
                    pattern[..n]
                        .iter()
                        .map(|p| v.get(*p as usize).cloned().flatten())
                        .collect()
                }
                E::As {
                    expr,
                    convert: None,
                    ..
                } => self.val(expr)?,
                E::As {
                    expr,
                    convert: Some(_),
                    ..
                } => {
                    if tagged(&self.val(expr)?) {
                        return Err("ExactMoveNumericalConvertUnsupported".into());
                    }
                    unknown
                }
                E::Select { condition, accept, reject } => {
                    // A Select is eager: visit its condition and both emitted value arms.
                    // No branch is chosen, even for a literal condition. A condition is
                    // an observable use, not a value-copy edge.
                    self.edge(h, &[condition], false)?;
                    let a = self.val(accept)?;
                    let b = self.val(reject)?;
                    let condition_matches = match &self.types[&condition.index()] {
                        naga::TypeInner::Scalar(s) => *s == naga::Scalar::BOOL,
                        naga::TypeInner::Vector { size, scalar } => {
                            *scalar == naga::Scalar::BOOL
                                && matches!(&self.types[&h.index()],
                                    naga::TypeInner::Vector { size: result, .. } if result == size)
                        }
                        _ => false,
                    };
                    if !condition_matches
                        || self.types[&accept.index()] != self.types[&reject.index()]
                        || self.types[&accept.index()] != self.types[&h.index()]
                        || a.len() != n || b.len() != n
                    {
                        return Err("ExactMoveSelectShapeUnsupported".into());
                    }
                    a.into_iter().zip(b).map(|(a, b)| {
                        if a == b {
                            // Includes bits, MOV source word/lane and opaque EXP handle.
                            Ok(a)
                        } else if tagged(&[a, b]) {
                            // One Atom cannot represent alternative origins (even equal
                            // bits) or a tracked/untracked union. Refuse without dropping it.
                            Err("ExactMoveSelectMergeUnsupported".into())
                        } else {
                            Ok(None)
                        }
                    }).collect::<Result<Vec<_>, String>>()?
                }
                E::Binary { op, left, right } => {
                    let allowed = matches!(
                        op,
                        naga::BinaryOperator::Add
                            | naga::BinaryOperator::Subtract
                            | naga::BinaryOperator::Multiply
                    );
                    self.edge(h, &[left, right], allowed)?;
                    unknown
                }
                E::Math {
                    fun,
                    arg,
                    arg1,
                    arg2,
                    arg3,
                } => {
                    let mut args = vec![arg];
                    args.extend(arg1);
                    args.extend(arg2);
                    args.extend(arg3);
                    self.edge(
                        h,
                        &args,
                        matches!(fun, naga::MathFunction::Dot | naga::MathFunction::Exp2),
                    )?;
                    if self.opaque.contains(&h) {
                        if fun != naga::MathFunction::Exp2
                            || args.len() != 1
                            || n != 1
                            || self.f.expression_controls.get(&h)
                                != Some(&naga::ArithmeticControl::Exp2F32NoRefactoringV1)
                        {
                            return Err("OpaqueExpSeedMismatch".into());
                        }
                        vec![Some(Atom {
                            bits: None,
                            origin: None,
                            opaque: Some(h),
                        })]
                    } else {
                        unknown
                    }
                }
                // Also the source module's exact float sign flip (D3D negate modifier).
                E::Unary { op: naga::UnaryOperator::Negate, expr }
                    if self.types[&expr.index()] == self.types[&h.index()]
                    && matches!(self.types[&h.index()], naga::TypeInner::Scalar(naga::Scalar { kind: naga::ScalarKind::Float, width: 4 }) | naga::TypeInner::Vector { scalar: naga::Scalar { kind: naga::ScalarKind::Float, width: 4 }, .. }) => {
                    // The writer's position adjustment is pure, but is not a
                    // supported tracked consumer. Never discard MOV/EXP atoms.
                    self.edge(h, &[expr], false)?;
                    unknown
                }
                E::CallResult(_) => unknown,
                e => return Err(format!("ExactMoveExpressionUnsupported: {h:?}: {e:?}")),
            };
            self.out.values.insert(h.index(), v.clone());
            Ok(v)
        }
        fn edge(
            &mut self,
            h: Handle<E>,
            args: &[Handle<E>],
            supported: bool,
        ) -> Result<(), String> {
            for (ordinal, &a) in args.iter().enumerate() {
                for (lane, atom) in self.val(a)?.into_iter().enumerate() {
                    if let Some(atom) = atom {
                        if atom.opaque.is_some()
                            && (!supported
                                || self.f.expression_controls.get(&h)
                                    != Some(&naga::ArithmeticControl::NoContraction))
                        {
                            return Err("OpaqueExpOrdinaryOrUnsupportedConsumer".into());
                        }
                        if atom.origin.is_some() && !supported {
                            return Err("ExactMoveConsumerUnsupported".into());
                        }
                        self.out.uses.push(Use {
                            producer: h,
                            operand: a,
                            ordinal,
                            lane: lane as u8,
                            atom,
                        });
                    }
                }
            }
            Ok(())
        }
        fn block(&mut self, b: &naga::Block) -> Result<(), String> {
            for s in b.iter() {
                self.statement += 1;
                match s {
                    S::Emit(range) => {
                        for h in range.clone() {
                            self.eval(h)?;
                        }
                    }
                    S::Store { pointer, value } => {
                        let mut v = self.val(*value)?;
                        let matches: Vec<_> = self
                            .seeds
                            .iter()
                            .enumerate()
                            .filter(|(_, s)| s.pointer == *pointer && s.value == *value)
                            .collect();
                        if matches.len() > 1 {
                            return Err("ExactMoveAmbiguousAssignment".into());
                        }
                        if let Some((i, seed)) = matches.first() {
                            if self.used.contains(i) {
                                return Err("ExactMoveRepeatedAssignment".into());
                            }
                            self.used.push(*i);
                            for &(lane, bits, word, dest) in &seed.lanes {
                                let a = v
                                    .get_mut(lane as usize)
                                    .and_then(Option::as_mut)
                                    .ok_or("ExactMoveAssignmentNotExact")?;
                                if a.bits != Some(bits)
                                    || (a.origin.is_some() || a.opaque.is_some())
                                {
                                    return Err("ExactMoveAssignmentBitsMismatch".into());
                                }
                                a.origin = Some((word, dest));
                            }
                        }
                        if let Some((l, k)) = self.pointer(*pointer) {
                            let local = self.locals.get_mut(&l).ok_or("ExactMoveLocalMissing")?;
                            let slot = local
                                .get_mut(k..k + v.len())
                                .ok_or("ExactMoveStoreLaneUnsupported")?;
                            for old in slot.iter().flatten() {
                                if let Some((w, d)) = old.origin {
                                    self.out.overwrites.push((self.statement, w, d));
                                }
                            }
                            slot.clone_from_slice(&v);
                            self.out.assignments.push(Assignment {
                                statement: self.statement,
                                pointer: *pointer,
                                value: *value,
                                local: l,
                                first_lane: k,
                                values: v,
                            });
                        } else if let Some((g, k)) = self.output_pointer(*pointer) {
                            // Every output store is an observable escape, even
                            // before an overwrite. Keep untracked exact bits for
                            // subsequent output reads and position adjustment.
                            if tagged(&v) { return Err("ExactMoveOutputEscapeUnsupported".into()); }
                            if matches!(self.f.expressions[*pointer], E::GlobalVariable(_)) {
                                self.outputs.insert(g, v);
                            } else {
                                self.outputs.get_mut(&g).ok_or("ExactMoveOutputWriteBeforeInitialization")?
                                    .get_mut(k..k+v.len()).ok_or("ExactMoveOutputLaneUnsupported")?.clone_from_slice(&v);
                            }
                        } else {
                            return Err("ExactMoveMemoryEscapeUnsupported".into());
                        }
                    }
                    S::Return { value } => {
                        if let Some(v) = value {
                            if tagged(&self.val(*v)?) {
                                return Err("ExactMoveReturnEscapeUnsupported".into());
                            }
                        }
                    }
                    S::Block(b) => self.block(b)?,
                    // Calls may observe or mutate pointees without tagged value arguments.
                    // Refuse them in seeded and imported endpoint analysis alike.
                    S::Call { .. } => return Err("ExactMoveCallUnsupported".into()),
                    _ => return Err("ExactMoveControlFlowOrEffectUnsupported".into()),
                }
            }
            Ok(())
        }
    }
    fn global(m: &naga::Module, h: Handle<E>, depth: usize) -> Result<Vec<Option<Atom>>, String> {
        if depth > 64 {
            return Err("ExactMoveConstantDepthUnsupported".into());
        }
        let a = |bits| {
            vec![Some(Atom {
                bits: Some(bits),
                origin: None,
                opaque: None,
            })]
        };
        Ok(match &m.global_expressions[h] {
            E::Literal(Literal::U32(v)) => a(*v),
            E::Literal(Literal::I32(v)) => a(*v as u32),
            E::Literal(Literal::F32(v)) => a(v.to_bits()),
            E::Constant(c) => global(m, m.constants[*c].init, depth + 1)?,
            E::ZeroValue(ty) => {
                let n = match m.types[*ty].inner {
                    naga::TypeInner::Scalar(s) if s.width == 4 => 1,
                    naga::TypeInner::Vector { size, scalar } if scalar.width == 4 => size as usize,
                    _ => 0,
                };
                vec![
                    Some(Atom {
                        bits: Some(0),
                        opaque: None,
                        origin: None
                    });
                    n
                ]
            }
            E::Compose { components, .. } => {
                let mut v = vec![];
                for c in components {
                    v.extend(global(m, *c, depth + 1)?)
                }
                v
            }
            E::Splat { size, value } => {
                vec![global(m, *value, depth + 1)?[0].clone(); *size as usize]
            }
            E::As {
                expr,
                convert: None,
                ..
            } => global(m, *expr, depth + 1)?,
            e => return Err(format!("ExactMoveConstantUnsupported: {e:?}")),
        })
    }
    let mut run = Run {
        interface,
        m,
        f,
        seeds,
        opaque,
        widths,
        types,
        uniform: BTreeMap::new(),
        clean_aggregate: std::collections::BTreeSet::new(),
        locals: BTreeMap::new(),
        outputs: BTreeMap::new(),
        out: Analysis {
            values: BTreeMap::new(),
            uses: vec![],
            assignments: vec![],
            overwrites: vec![],
        },
        used: vec![],
        statement: 0,
    };
    for (l, v) in f.local_variables.iter() {
        let n = match m.types[v.ty].inner {
            naga::TypeInner::Scalar(s) if s.width == 4 => 1,
            naga::TypeInner::Vector { size, scalar } if scalar.width == 4 => size as usize,
            _ => 0,
        };
        let init = if let Some(h) = v.init {
            run.val(h)?
        } else {
            vec![None; n]
        };
        run.locals.insert(l.index(), init);
    }
    run.block(&f.body)?;
    if run.used.len() != seeds.len() {
        return Err("ExactMoveAssignmentMissing".into());
    }
    Ok(run.out)
}

use super::*;
use naga::correspondence::{Disposition, ExpressionRef, Owner};

/// Execution-local fingerprint; package/source identities pin the Debug representation.
pub fn module_identity(module: &naga::Module) -> String {
    crate::source_hash(format!("{module:?}").as_bytes())
}
#[derive(Clone, Debug)]
pub struct DeadProducer {
    pub binding: ProducerBinding,
    pub removed_at_revision: u32,
    pub pre_module: String,
    pub reason: &'static str,
}
#[derive(Clone, Debug)]
pub enum TransformKind {
    VertexBody {
        entry: usize,
        function: Handle<naga::Function>,
    },
    Compaction,
    ResourceBindings,
    Interface,
    ExactZeroLod,
    CallerNull,
}
#[derive(Clone, Debug)]
pub struct ReceiptTransform {
    pub kind: TransformKind,
    pub pre_module: String,
    pub post_module: String,
    pub pre_receipt: String,
    pub post_receipt: String,
    pub revision: u32,
    pub replacements: Vec<Replacement>,
    pub resources: Vec<ResourceChange>,
}
#[derive(Clone, Debug)]
pub struct ResourceChange {
    pub global: Handle<naga::GlobalVariable>,
    pub old: naga::GlobalVariable,
    pub new: naga::GlobalVariable,
    pub old_type: naga::TypeInner,
    pub new_type: naga::TypeInner,
}
#[derive(Clone, Debug)]
pub struct Replacement {
    pub reference: OwnedExpression,
    pub old: Expression,
    pub new: Expression,
}
pub fn reference(r: &OwnedExpression) -> ExpressionRef {
    ExpressionRef {
        owner: match r.owner {
            FunctionOwner::Function(h) => Owner::Function(h),
            FunctionOwner::EntryPoint { index, .. } => Owner::EntryPoint(index),
        },
        expression: r.expression,
    }
}
pub(super) fn function<'a>(
    m: &'a naga::Module,
    o: &FunctionOwner,
) -> Result<&'a naga::Function, String> {
    match o {
        FunctionOwner::Function(h) => m.functions.try_get(*h).map_err(|_| "owner missing".into()),
        FunctionOwner::EntryPoint { index, name } => m
            .entry_points
            .get(*index)
            .filter(|e| e.name == *name)
            .map(|e| &e.function)
            .ok_or("entry missing".into()),
    }
}
fn owner(m: &naga::Module, o: Owner) -> Result<FunctionOwner, String> {
    Ok(match o {
        Owner::Function(h) => {
            m.functions
                .try_get(h)
                .map_err(|_| "mapped function missing")?;
            FunctionOwner::Function(h)
        }
        Owner::EntryPoint(index) => FunctionOwner::EntryPoint {
            index,
            name: m
                .entry_points
                .get(index)
                .ok_or("mapped entry missing")?
                .name
                .clone(),
        },
    })
}
pub(super) fn check_binding_type(
    m: &naga::Module,
    f: &naga::Function,
    b: &ProducerBinding,
) -> Result<(), String> {
    let mut t = naga::front::Typifier::new();
    let ctx = naga::proc::ResolveContext::with_locals(m, &f.local_variables, &f.arguments);
    for (h, width) in std::iter::once((b.producer.expression, b.width)).chain(
        b.operands
            .iter()
            .zip(&b.input_widths)
            .map(|(a, w)| (a.expression, *w)),
    ) {
        t.grow(h, &f.expressions, &ctx).map_err(|e| e.to_string())?;
        let (scalar, n) = match t.get(h, &m.types) {
            naga::TypeInner::Scalar(s) => (*s, 1),
            naga::TypeInner::Vector { size, scalar } => (*scalar, *size as u8),
            _ => return Err("PreciseBindingTypeMismatch".into()),
        };
        if matches!(b.role, ProducerRole::CompareLess | ProducerRole::MaxCompare) {
            // Bool comparison result over f32 operands of the same lane count.
            let producer = h == b.producer.expression;
            let ok = if producer {
                scalar.kind == naga::ScalarKind::Bool && scalar.width == naga::BOOL_WIDTH
            } else {
                scalar == naga::Scalar::F32
            };
            if b.kind != crate::build::Kind::B || b.scalar_bytes != 4 || !ok || n != width.get() {
                return Err("PreciseBindingTypeMismatch".into());
            }
            continue;
        }
        let expected = match b.kind {
            crate::build::Kind::F => naga::ScalarKind::Float,
            crate::build::Kind::U => naga::ScalarKind::Uint,
            _ => return Err("unsupported receipt kind".into()),
        };
        if scalar.kind != expected || scalar.width != b.scalar_bytes || n != width.get() {
            return Err("PreciseBindingTypeMismatch".into());
        }
    }
    Ok(())
}
impl PrecisionReceipt {
    pub fn revision(&self) -> u32 {
        self.revision
    }
    pub fn dead(&self) -> &[DeadProducer] {
        &self.dead
    }
    pub fn transforms(&self) -> &[ReceiptTransform] {
        &self.transforms
    }
    pub fn identity(&self) -> String {
        // Self-digests are omitted to avoid circular hashing; the complete transition data is included.
        let mut history = self.transforms.clone();
        // Raw source declarations are immutable source identity, never remapped handles.
        let raw = format!("{:?}", self.raw_declarations582);
        for t in &mut history {
            t.post_receipt.clear();
        }
        crate::source_hash(
            format!(
                "{:?}{:?}{:?}{:?}{:?}{:?}{:?}{:?}{:?}{:?}{:?}{:?}{raw}",
                self.unary_proofs,
                self.dead_unary_uses,
                self.dead_exact_uses,
                self.exact_moves,
                self.exact_proofs,
                self.records,
                self.bindings,
                self.visited,
                self.dead,
                self.revision,
                self.module_identity,
                history
            )
            .as_bytes(),
        )
    }
    pub fn seal_initial(&mut self, m: &naga::Module, source: Option<&str>) -> Result<(), String> {
        if self.module_identity.is_some() || self.revision != 0 {
            return Err("receipt already sealed".into());
        }
        let mut next = self.clone();
        next.refresh_exact(m)?;
        next.refresh_unary(m)?;
        next.validate(m, source)?;
        *self = next;
        self.module_identity = Some(module_identity(m));
        Ok(())
    }
    fn begin(&self, pre: &naga::Module) -> Result<(), String> {
        if self.is_precision_bearing() && self.module_identity.is_none() {
            return Err("PreciseUnsealedReceipt".into());
        }
        self.validate(pre, self.records.first().map(|r| r.source_sha.as_str()))
    }
    fn finish(
        &mut self,
        pre: &naga::Module,
        post: &naga::Module,
        kind: TransformKind,
        old_id: String,
        replacements: Vec<Replacement>,
    ) -> Result<(), String> {
        self.revision = self
            .revision
            .checked_add(1)
            .ok_or("receipt revision overflow")?;
        for b in &mut self.bindings {
            b.producer.module_revision = self.revision;
            for a in &mut b.operands {
                a.module_revision = self.revision;
            }
        }
        for mov in &mut self.exact_moves {
            for a in &mut mov.assignments {
                a.pointer.module_revision = self.revision;
                a.value.module_revision = self.revision;
            }
        }
        self.refresh_exact(post)?;
        self.refresh_unary(post)?;
        self.module_identity = Some(module_identity(post));
        self.validate(post, self.records.first().map(|r| r.source_sha.as_str()))?;
        let post_receipt = String::new();
        let resources = if matches!(kind, TransformKind::ResourceBindings) {
            pre.global_variables
                .iter()
                .filter_map(|(h, g)| {
                    post.global_variables
                        .try_get(h)
                        .ok()
                        .filter(|n| format!("{g:?}") != format!("{n:?}"))
                        .map(|n| ResourceChange {
                            global: h,
                            old: g.clone(),
                            new: n.clone(),
                            old_type: pre.types[g.ty].inner.clone(),
                            new_type: post.types[n.ty].inner.clone(),
                        })
                })
                .collect()
        } else {
            vec![]
        };
        self.transforms.push(ReceiptTransform {
            kind,
            pre_module: module_identity(pre),
            post_module: module_identity(post),
            pre_receipt: old_id,
            post_receipt,
            revision: self.revision,
            replacements,
            resources,
        });
        let digest = self.identity();
        self.transforms.last_mut().unwrap().post_receipt = digest;
        Ok(())
    }
    /// Exact source-body clone, with only entry bindings removed; wrapper has no source controls.
    pub fn relocate_vertex_body(
        &self,
        pre: &naga::Module,
        post: &naga::Module,
        entry: usize,
        h: Handle<naga::Function>,
    ) -> Result<Self, String> {
        self.begin(pre)?;
        if self.is_precision_bearing()
            && self
                .transforms
                .iter()
                .any(|t| matches!(t.kind, TransformKind::VertexBody { .. }))
        {
            return Err("PreciseRepeatedStageWrapperLifecycleUnsupported".into());
        }
        for (h, t) in pre.types.iter() {
            if post.types.get_handle(h).ok() != Some(t) {
                return Err("PreciseRelocationTypeMutation".into());
            }
        }
        for (h, g) in pre.global_variables.iter() {
            if format!("{g:?}")
                != format!(
                    "{:?}",
                    post.global_variables
                        .try_get(h)
                        .map_err(|_| "global missing")?
                )
            {
                return Err("PreciseRelocationGlobalMutation".into());
            }
        }
        let ep = pre.entry_points.get(entry).ok_or("old entry missing")?;
        if ep.stage != naga::ShaderStage::Vertex {
            return Err("unsupported phase relocation".into());
        }
        let mut expected = ep.function.clone();
        expected.name = Some("d2r_original_vertex_body52".into());
        for a in &mut expected.arguments {
            a.binding = None;
        }
        if let Some(r) = &mut expected.result {
            r.binding = None;
        }
        if format!("{expected:?}")
            != format!(
                "{:?}",
                post.functions
                    .try_get(h)
                    .map_err(|_| "relocated function missing")?
            )
            || !post.entry_points[entry]
                .function
                .expression_controls
                .is_empty()
        {
            return Err("PreciseBodyRelocationMismatch".into());
        }
        // Other original owners cannot be changed as part of an entry-body relocation.
        for (old_h, old_f) in pre.functions.iter() {
            if format!("{old_f:?}")
                != format!(
                    "{:?}",
                    post.functions
                        .try_get(old_h)
                        .map_err(|_| "old function missing")?
                )
            {
                return Err("PreciseUnmappedOtherOwnerMutation".into());
            }
        }
        let wrapper = &post.entry_points[entry].function;
        let calls = wrapper
            .body
            .iter()
            .filter_map(|s| {
                if let naga::Statement::Call {
                    function,
                    arguments,
                    result,
                } = s
                {
                    Some((*function, arguments, result))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();
        if calls.len() != 1 || calls[0].0 != h || calls[0].1.len() != expected.arguments.len() {
            return Err("PreciseRelocationWrapperCallMismatch".into());
        }
        if !matches!(wrapper.body.last(),Some(naga::Statement::Return{value}) if value==calls[0].2)
        {
            return Err("PreciseRelocationWrapperReturnMismatch".into());
        }
        let mut next = self.clone();
        for b in &mut next.bindings {
            if b.producer.owner
                == (FunctionOwner::EntryPoint {
                    index: entry,
                    name: ep.name.clone(),
                })
            {
                b.producer.owner = FunctionOwner::Function(h);
                for a in &mut b.operands {
                    a.owner = FunctionOwner::Function(h);
                }
            }
        }
        for mov in &mut next.exact_moves {
            for a in &mut mov.assignments {
                if a.pointer.owner
                    == (FunctionOwner::EntryPoint {
                        index: entry,
                        name: ep.name.clone(),
                    })
                {
                    a.pointer.owner = FunctionOwner::Function(h);
                    a.value.owner = FunctionOwner::Function(h);
                }
            }
        }
        next.finish(
            pre,
            post,
            TransformKind::VertexBody { entry, function: h },
            self.identity(),
            vec![],
        )?;
        Ok(next)
    }
    /// Runs the actual compactor itself: a caller cannot submit a stale/fabricated report.
    pub fn compact(
        &self,
        pre: &naga::Module,
        keep: naga::compact::KeepUnused,
    ) -> Result<(naga::Module, Self, naga::correspondence::CompactionReport), String> {
        self.begin(pre)?;
        let mut post = pre.clone();
        let report = naga::compact::compact_with_report(&mut post, keep);
        if report.revision != 2 {
            return Err("compaction report revision".into());
        }
        let remap = |r: &OwnedExpression| -> Result<Option<OwnedExpression>, String> {
            let old = reference(r);
            let row = report
                .owners
                .iter()
                .find(|x| x.old == old.owner)
                .ok_or("owner map missing")?;
            match row
                .expressions
                .iter()
                .find(|(h, _)| *h == r.expression)
                .ok_or("expression map missing")?
                .1
            {
                Disposition::Removed => Ok(None),
                Disposition::Survives(e) => Ok(Some(OwnedExpression {
                    owner: owner(&post, e.owner)?,
                    expression: e.expression,
                    module_revision: r.module_revision,
                })),
            }
        };
        let mut next = self.clone();
        next.bindings.clear();
        for mov in &mut next.exact_moves {
            for a in &mut mov.assignments {
                a.pointer =
                    remap(&a.pointer)?.ok_or("ExactMoveAssignmentPointerRemovedUnsupported")?;
                a.value = remap(&a.value)?.ok_or("ExactMoveAssignmentValueRemovedUnsupported")?;
            }
        }
        for b in &self.bindings {
            match remap(&b.producer)? {
                None => next.dead.push(DeadProducer {
                    binding: b.clone(),
                    removed_at_revision: self.revision + 1,
                    pre_module: module_identity(pre),
                    reason: "actual compaction removed pure arithmetic result",
                }),
                Some(p) => {
                    let mut b = b.clone();
                    b.producer = p;
                    b.operands = b
                        .operands
                        .iter()
                        .map(|r| remap(r)?.ok_or("live producer operand removed".into()))
                        .collect::<Result<_, String>>()?;
                    next.bindings.push(b);
                }
            }
        }
        // Map each actual use independently through the compactor, never through equal handles.
        let mut expected = vec![];
        for proof in &self.exact_proofs {
            for usage in &proof.analysis.uses {
                if usage.atom.origin.is_none() {
                    continue;
                }
                let old = OwnedExpression {
                    module_revision: self.revision,
                    owner: proof.owner.clone(),
                    expression: usage.producer,
                };
                if let Some(producer) = remap(&old)? {
                    let operand = remap(&OwnedExpression {
                        expression: usage.operand,
                        ..old
                    })?
                    .ok_or("ExactMoveLiveOperandRemoved")?;
                    if operand.owner != producer.owner {
                        return Err("ExactMoveCompactionOwnerMismatch".into());
                    }
                    let mut u = usage.clone();
                    u.producer = producer.expression;
                    u.operand = operand.expression;
                    expected.push((producer.owner, u));
                } else {
                    next.dead_exact_uses.push(DeadExactUse {
                        owner: proof.owner.clone(),
                        usage: usage.clone(),
                        removed_at_revision: self.revision + 1,
                        pre_module: module_identity(pre),
                    });
                }
            }
        }
        let actual = next
            .analyze_exact(&post)?
            .into_iter()
            .flat_map(|p| {
                p.analysis
                    .uses
                    .into_iter()
                    .filter(|u| u.atom.origin.is_some())
                    .map(move |u| (p.owner.clone(), u))
            })
            .collect::<Vec<_>>();
        if expected != actual {
            return Err("ExactMoveCompactionUseMismatch".into());
        }
        self.check_unary_compaction(&mut next, &post, &remap, pre)?;
        next.finish(
            pre,
            &post,
            TransformKind::Compaction,
            self.identity(),
            vec![],
        )?;
        Ok((post, next, report))
    }
    /// Same arenas, checked old expressions and explicit replacement policy. Existing arithmetic is never replaced.
    pub fn unchanged_arithmetic(
        &self,
        pre: &naga::Module,
        post: &naga::Module,
        kind: TransformKind,
    ) -> Result<Self, String> {
        self.begin(pre)?;
        let mut replacements = vec![];
        if !self.is_precision_bearing() {
            let mut next = self.clone();
            if self.analyze_unary(pre)? != next.analyze_unary(post)? {
                return Err("OpaqueExpTransformUseChange".into());
            }
            next.finish(pre, post, kind, self.identity(), replacements)?;
            return Ok(next);
        }
        if pre.functions.len() != post.functions.len()
            || pre.entry_points.len() != post.entry_points.len()
        {
            return Err("PreciseUnmappedOwnerChange".into());
        }
        for (h, t) in pre.types.iter() {
            let n = post
                .types
                .get_handle(h)
                .map_err(|_| "unmapped type removal")?;
            if format!("{t:?}") != format!("{n:?}") {
                let mut normalized = t.clone();
                if matches!(kind, TransformKind::Interface) {
                    if let naga::TypeInner::Struct { members, .. } = &mut normalized.inner {
                        for m in members {
                            m.binding = None
                        }
                    }
                }
                if format!("{normalized:?}") != format!("{n:?}") {
                    return Err("PreciseUnmappedTypeReplacement".into());
                }
            }
        }
        for (h, g) in pre.global_variables.iter() {
            let n = post
                .global_variables
                .try_get(h)
                .map_err(|_| "unmapped global removal")?;
            let mut expected = g.clone();
            if matches!(kind, TransformKind::ResourceBindings) {
                expected.binding = n.binding.clone();
                if g.ty != n.ty {
                    match (&pre.types[g.ty].inner, &post.types[n.ty].inner) {
                        (
                            naga::TypeInner::Image {
                                dim: a,
                                arrayed: b,
                                class:
                                    naga::ImageClass::Storage {
                                        format: x,
                                        access: y,
                                    },
                            },
                            naga::TypeInner::Image {
                                dim: c,
                                arrayed: d,
                                class:
                                    naga::ImageClass::Storage {
                                        format: z,
                                        access: w,
                                    },
                            },
                        ) if a == c
                            && b == d
                            && y == w
                            && naga::Scalar::from(*x).kind == naga::Scalar::from(*z).kind =>
                        {
                            expected.ty = n.ty
                        }
                        _ => return Err("PreciseUnsupportedResourceSubstitution".into()),
                    }
                }
            }
            if format!("{expected:?}") != format!("{n:?}") {
                return Err("PreciseUnmappedGlobalReplacement".into());
            }
        }
        let owners = pre
            .functions
            .iter()
            .map(|(h, _)| FunctionOwner::Function(h))
            .chain(pre.entry_points.iter().enumerate().map(|(index, e)| {
                FunctionOwner::EntryPoint {
                    index,
                    name: e.name.clone(),
                }
            }));
        for o in owners {
            let a = function(pre, &o)?;
            let b = function(post, &o)?;
            if matches!(
                kind,
                TransformKind::ResourceBindings | TransformKind::ExactZeroLod
            ) && (format!("{:?}", a.body) != format!("{:?}", b.body)
                || format!("{:?}", a.local_variables) != format!("{:?}", b.local_variables))
            {
                return Err("PreciseUnmappedBodyOrLocalMutation".into());
            }
            for (h, e) in a.expressions.iter() {
                let n = b
                    .expressions
                    .try_get(h)
                    .map_err(|_| "PreciseUnmappedExpressionRemoval")?;
                if format!("{e:?}") == format!("{n:?}") {
                    continue;
                }
                // A NULL replacement is permitted only for operations checked by the caller's sealed capability.
                // Direct producer/operand replacement is deliberately unsupported until a reaching-use rule exists.
                if self.bindings.iter().any(|p| {
                    p.producer.owner == o
                        && (p.producer.expression == h
                            || p.operands.iter().any(|v| v.expression == h))
                }) {
                    return Err("PreciseProducerOrOperandReplacementUnsupported".into());
                }
                if matches!(kind, TransformKind::CallerNull)
                    && (!self.bindings.is_empty() || !self.exact_moves.is_empty())
                {
                    return Err("PreciseCallerNullReachingUseRemapUnavailable".into());
                }
                let allowed = match kind {
                    TransformKind::ExactZeroLod => match (e, n) {
                        (
                            Expression::ImageSample {
                                image,
                                level: naga::SampleLevel::Exact(old),
                                depth_ref: None,
                                ..
                            },
                            Expression::ImageSample {
                                level: naga::SampleLevel::Exact(new),
                                ..
                            },
                        ) => {
                            let mut normalized = n.clone();
                            if let Expression::ImageSample { level, .. } = &mut normalized {
                                *level = naga::SampleLevel::Exact(*old);
                            }
                            matches!(a.expressions[*image],Expression::GlobalVariable(g) if matches!(pre.types[pre.global_variables[g].ty].inner,naga::TypeInner::Image{class:naga::ImageClass::Depth{multi:false},..}))
                                && format!("{normalized:?}") == format!("{e:?}")
                                && matches!(a.expressions[*old],Expression::Literal(naga::Literal::F32(v)) if v.to_bits()==0)
                                && matches!(
                                    b.expressions[*new],
                                    Expression::Literal(
                                        naga::Literal::I32(0) | naga::Literal::U32(0)
                                    )
                                )
                        }
                        _ => false,
                    },
                    TransformKind::CallerNull => {
                        matches!(
                            e,
                            Expression::ImageSample { .. } | Expression::Select { .. }
                        ) && matches!(n, Expression::ZeroValue(_))
                    }
                    _ => false,
                };
                if !allowed {
                    return Err(format!("PreciseUnmappedReplacement: {o:?}/{h:?}"));
                }
                replacements.push(Replacement {
                    reference: OwnedExpression {
                        owner: o.clone(),
                        expression: h,
                        module_revision: self.revision,
                    },
                    old: e.clone(),
                    new: n.clone(),
                });
            }
        }
        let mut next = self.clone();
        let proofs = next.analyze_exact(post)?;
        for old in &self.exact_proofs {
            let new = proofs
                .iter()
                .find(|p| p.owner == old.owner)
                .ok_or("ExactMoveOwnerRemoved")?;
            if old.analysis.uses != new.analysis.uses
                || old.analysis.assignments != new.analysis.assignments
                || old.analysis.overwrites != new.analysis.overwrites
            {
                return Err("ExactMoveTransformUseChangeUnsupported".into());
            }
        }
        if self.analyze_unary(pre)? != next.analyze_unary(post)? {
            return Err("OpaqueExpTransformUseChange".into());
        }
        next.finish(pre, post, kind, self.identity(), replacements)?;
        Ok(next)
    }
}

impl PrecisionReceipt {
    pub(super) fn validate_coverage(&self) -> Result<(), String> {
        let words = self
            .records
            .iter()
            .map(|r| r.word)
            .collect::<std::collections::BTreeSet<_>>();
        let visits = self
            .visited
            .iter()
            .copied()
            .collect::<std::collections::BTreeSet<_>>();
        if self
            .records
            .iter()
            .any(|r| r.instruction.precise_mask() != 0)
            && (words.len() != self.records.len()
                || visits.len() != self.visited.len()
                || !visits.is_subset(&words))
        {
            return Err("PreciseSourceInventoryAmbiguous".into());
        }

        for r in self.records.iter() {
            let bytes: Vec<u8> = r.words.iter().flat_map(|w| w.to_le_bytes()).collect();
            if crate::source_hash(&bytes) != r.digest {
                return Err("PreciseSourceDigestMismatch".into());
            }
            if r.instruction.precise_mask() == 0 {
                continue;
            }
            let bindings: Vec<_> = self
                .bindings
                .iter()
                .chain(self.dead.iter().map(|d| &d.binding))
                .filter(|b| b.source_word == r.word)
                .collect();
            if !self.visited.contains(&r.word) {
                if !bindings.is_empty() {
                    return Err("binding for unvisited source".into());
                }
                continue;
            }
            if r.instruction.name() == "mov" && register_copy_lanes(r).is_err() {
                if !bindings.is_empty()
                    || self
                        .exact_moves
                        .iter()
                        .filter(|m| m.source_word == r.word)
                        .count()
                        != 1
                {
                    return Err("ExactMoveCoverageMissing".into());
                }
                continue;
            }
            let unary = r.instruction.name() == "exp";
            if unary {
                scalar_exp_lane(r)?;
            }
            let round = r.instruction.name() == "round_ni";
            if round {
                round_ni_lanes(r)?;
            }
            let less = r.instruction.name() == "lt";
            if less {
                less_lanes(r)?;
            }
            let conditional = r.instruction.name() == "movc";
            let frac = r.instruction.name() == "frc";
            let maximum = r.instruction.name() == "max";
            if maximum {
                max_lanes(r)?;
            }
            if frac {
                frac_lanes(r)?;
            }
            if conditional {
                conditional_move_lanes(r)?;
            }
            let copy = r.instruction.name() == "mov";
            let shift = r.instruction.name() == "ishl";
            let raw = r.instruction.name() == "ld_raw";
            let sample = r.instruction.name()=="sample_l";
            if sample{sample_source648(r)?;}
            let bit_exact = copy || shift || raw || sample || conditional;
            let tolerance = if matches!(r.instruction.name(), "sincos" | "rsq" | "div") {
                Some(tolerance_lanes(r)?)
            } else {
                None
            };
            let arity = if let Some(t) = &tolerance {
                if t.op == ToleranceOp::Div { 2 } else { 1 }
            } else if unary || round || copy || raw { 1 } else if conditional { 3 } else { 2 };
            let dest = if let Some(t) = &tolerance {
                t.destination
            } else if matches!(r.instruction.name(), "imul" | "umul") {
                1
            } else {
                0
            };
            let d = r
                .destinations
                .iter()
                .find(|d| d.ordinal == dest)
                .ok_or("missing destination")?;
            let mut seen = std::collections::BTreeSet::new();
            for b in bindings {
                if b.instance != 0
                    || b.destination != dest
                    || b.operands.len() != if frac { if b.role == ProducerRole::FracFloor { 1 } else { 2 } } else { arity }
                    || b.input_widths.len() != b.operands.len()
                    || b.original_lanes.len() != b.packed_positions.len()
                {
                    return Err("PreciseSourceCoverageMismatch".into());
                }
                let dot = r.instruction.name().starts_with("dp");
                let expected_kind = if less || maximum {
                    crate::build::Kind::B
                } else if sample || matches!(
                    r.instruction.name(),
                    "exp" | "round_ni" | "frc" | "sincos" | "rsq" | "div" | "add" | "mul" | "dp2" | "dp3" | "dp4"
                ) {
                    crate::build::Kind::F
                } else {
                    crate::build::Kind::U
                };
                let expected_role = if sample {ProducerRole::SampleExplicitLod648}else if raw {
                    ProducerRole::RawLoad582
                } else if copy {
                    ProducerRole::RegisterCopy
                } else if shift {
                    ProducerRole::LogicalShift
                } else if unary {
                    ProducerRole::Exp2Scalar
                } else if round {
                    ProducerRole::RoundNi
                } else if less {
                    ProducerRole::CompareLess
                } else if conditional {
                    ProducerRole::ConditionalMove
                } else if r.instruction.name() == "add" && r.instruction.saturate {
                    add_sat_lanes(r)?;
                    ProducerRole::SaturateAdd
                } else if let Some(t) = &tolerance {
                    t.op.role()
                } else if maximum {
                    ProducerRole::MaxCompare
                } else if frac {
                    if b.role == ProducerRole::FracFloor { ProducerRole::FracFloor } else { ProducerRole::FracSubtract }
                } else if dot {
                    ProducerRole::DotBroadcast
                } else if dest == 1 {
                    ProducerRole::LowMultiply
                } else {
                    ProducerRole::Elementwise
                };
                if b.kind != expected_kind
                    || b.role != expected_role
                    || b.scalar_bytes != 4
                    || b.width.get() != if dot { 1 } else { b.original_lanes.len() as u8 }
                {
                    return Err("PreciseSourceTypeOrRoleMismatch".into());
                }
                let input_width = if raw {
                    1
                } else if copy {
                    4
                } else if dot {
                    match r.instruction.name() {
                        "dp2" => 2,
                        "dp3" => 3,
                        _ => 4,
                    }
                } else {
                    b.width.get()
                };
                if if sample {b.input_widths.iter().map(|w|w.get()).collect::<Vec<_>>()!=[2,1]}else{b.input_widths.iter().any(|w| w.get() != input_width)} {
                    return Err("PreciseSourceInputTypeMismatch".into());
                }
                for (&lane, &position) in b.original_lanes.iter().zip(&b.packed_positions) {
                    if d.lanes.get(position as usize) != Some(&lane)
                        || !seen.insert(lane + if frac && b.role == ProducerRole::FracSubtract { 16 } else { 0 })
                        || b.controlled != (!bit_exact && r.instruction.precise_mask() & (1 << lane) != 0)
                    {
                        return Err("PreciseLaneCoverageMismatch".into());
                    }
                }
            }
            // A precise frc covers every lane once with each of its two controlled producers.
            let want: Vec<u8> = if frac { d.lanes.iter().copied().chain(d.lanes.iter().map(|l| l + 16)).collect() } else { d.lanes.clone() };
            if seen.into_iter().collect::<Vec<_>>() != want {
                return Err("PreciseSourceCoverageMissing".into());
            }
        }
        Ok(())
    }
}

//! Source scalar EXP and opaque reaching-use proof. No exponential evaluation.
use super::*;
use dxbc_reader::decode::{Register, Selection};
impl ProducerBinding {
    pub fn control(&self) -> Option<naga::ArithmeticControl> {
        (self.controlled && !matches!(self.role, ProducerRole::SampleExplicitLod648 | ProducerRole::RawLoad582 | ProducerRole::RegisterCopy | ProducerRole::ConditionalMove | ProducerRole::LogicalShift))
            .then_some(if self.role == ProducerRole::Exp2Scalar {
                naga::ArithmeticControl::Exp2F32NoRefactoringV1
            } else if matches!(self.role, ProducerRole::RoundNi | ProducerRole::FracFloor) {
                naga::ArithmeticControl::FloorF32NoRefactoringV1
            } else if self.role == ProducerRole::SaturateAdd {
                naga::ArithmeticControl::AddF32StrictV1
            } else if ToleranceOp::of_role(self.role).is_some() {
                naga::ArithmeticControl::ToleranceF32NoRefactoringV1
            } else if matches!(self.role, ProducerRole::CompareLess | ProducerRole::MaxCompare) {
                naga::ArithmeticControl::LessF32NoRefactoringV1
            } else {
                naga::ArithmeticControl::NoContraction
            })
    }
}
pub fn scalar_exp_lane(r: &SourceInstruction) -> Result<(u8, u8), String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "ExpRawDecodeMismatch")?;
    let mut actual = decoded
        .instructions
        .first()
        .ok_or("ExpRawDecodeMismatch")?
        .clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("ExpRawDecodeMismatch".into());
    }
    if i.name() != "exp"
        || i.operands.len() != 2
        || r.flags.len() != 1
        || r.flags[0] & 1 == 0
        || r.reason != PrecisionReason::ExplicitMask
    {
        return Err("ExpPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| {
            o.modifier != 0
                || o.precision != 0
                || o.non_uniform
                || o.indices.iter().any(|i| i.relative.is_some())
        })
    {
        return Err("ExpModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let s = &i.operands[1];
    let Selection::Mask(mask) = d.selection else {
        return Err("ExpDestinationUnsupported".into());
    };
    if mask.count_ones() != 1
        || mask & !15 != 0
        || i.precise_mask() != mask
        || d.register != Register::Temp
        || d.indices.len() != 1
    {
        return Err("ExpScalarShapeUnsupported".into());
    }
    if !((s.register == Register::Temp && s.indices.len() == 1)
        || (s.register == Register::Immediate && s.indices.is_empty()))
    {
        return Err("ExpInputDomainUnsupported".into());
    }
    let lane = mask.trailing_zeros() as u8;
    let selected = selected_lane(s.selection, lane)?;
    if selected > 3
        || (s.register == Register::Immediate && s.immediate.get(selected as usize).is_none())
    {
        return Err("ExpSelectionUnsupported".into());
    }
    if r.destinations.len() != 1
        || r.destinations[0].ordinal != 0
        || r.destinations[0].null
        || r.destinations[0].mask != mask
        || r.destinations[0].lanes != [lane]
    {
        return Err("ExpDestinationInventoryMismatch".into());
    }
    Ok((lane, selected))
}
fn selected_lane(s: Selection, lane: u8) -> Result<u8, String> {
    Ok(match s {
        Selection::Mask(_) => lane,
        Selection::Scalar(c) => c,
        Selection::Swizzle(sw) => sw[lane as usize],
        Selection::None => return Err("ExpSelectionUnsupported".into()),
