}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UnaryUse {
    pub source_word: usize,
    pub source_operand: usize,
    pub source_lane: u8,
    pub edge: exact_eval::Use,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum UnaryDisposition {
    ProtectedConsumers,
    DeadPureCopy,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UnaryProof {
    pub producer: OwnedExpression,
    pub source_word: usize,
    pub destination_lane: u8,
    pub input_lane: u8,
    pub uses: Vec<UnaryUse>,
    pub disposition: UnaryDisposition,
    pub analysis: exact_eval::Analysis,
}
#[derive(Clone, Debug)]
pub struct DeadUnaryUse {
    pub proof: UnaryProof,
    pub usage: UnaryUse,
    pub removed_at_revision: u32,
    pub pre_module: String,
}
impl PrecisionReceipt {
    pub fn unary_proofs(&self) -> &[UnaryProof] {
        &self.unary_proofs
    }
    pub fn dead_unary_uses(&self) -> &[DeadUnaryUse] {
        &self.dead_unary_uses
    }
    pub(super) fn analyze_unary(&self, m: &naga::Module) -> Result<Vec<UnaryProof>, String> {
        let mut out = vec![];
        for b in self
            .bindings
            .iter()
            .filter(|b| matches!(b.role,ProducerRole::Exp2Scalar|ProducerRole::SampleExplicitLod648))
        {
            let source = self
                .records
                .iter()
                .find(|r| r.word == b.source_word)
                .ok_or("ExpSourceMissing")?;
            let (destination_lane, input_lane) = if b.role==ProducerRole::SampleExplicitLod648{sample_source648(source)?;(3,0)}else{scalar_exp_lane(source)?};
            let analysis = self.analyze_resources648(m,&b.producer.owner,&[],&[b.producer.expression])?;
            let mut uses = vec![];
            for edge in analysis.uses.iter().filter(|u| u.atom.opaque.is_some()) {
                let consumer = self
                    .bindings
                    .iter()
                    .find(|c| {
                        c.producer.owner == b.producer.owner
                            && c.producer.expression == edge.producer
                            && c.control() == Some(naga::ArithmeticControl::NoContraction)
                    })
                    .ok_or("ExpConsumerWithoutSourceControl")?;
                if consumer.operands.get(edge.ordinal).map(|a| a.expression) != Some(edge.operand) {
                    return Err("ExpConsumerOperandMismatch".into());
                }
                let r = self
                    .records
                    .iter()
                    .find(|r| r.word == consumer.source_word)
                    .ok_or("ExpConsumerSourceMissing")?;
                let (destinations, sources) = r
                    .instruction
                    .destinations_and_sources()
                    .ok_or("ExpConsumerSourceUnsupported")?;
                let lane = if consumer.role == ProducerRole::DotBroadcast {
                    edge.lane
                } else {
                    *consumer
                        .original_lanes
                        .get(edge.lane as usize)
                        .ok_or("ExpConsumerLaneMismatch")?
                };
                let operand = sources
                    .get(edge.ordinal)
                    .ok_or("ExpConsumerOperandMissing")?;
                if operand.modifier != 0
                    || operand.precision != 0
                    || operand.non_uniform
                    || operand.indices.iter().any(|i| i.relative.is_some())
                {
                    return Err("ExpConsumerModifierUnsupported".into());
                }
                uses.push(UnaryUse {
                    source_word: r.word,
                    source_operand: destinations.len() + edge.ordinal,
                    source_lane: selected_lane(operand.selection, lane)?,
                    edge: edge.clone(),
                });
            }
            let disposition = if uses.is_empty() {
                UnaryDisposition::DeadPureCopy
            } else {
                UnaryDisposition::ProtectedConsumers
            };
            out.push(UnaryProof {
                producer: b.producer.clone(),
                source_word: b.source_word,
                destination_lane,
                input_lane,
                uses,
                disposition,
                analysis,
            });
        }
        Ok(out)
    }
    pub(super) fn refresh_unary(&mut self, m: &naga::Module) -> Result<(), String> {
        self.unary_proofs = self.analyze_unary(m)?;
        Ok(())
    }
    pub(super) fn validate_unary(&self, m: &naga::Module) -> Result<(), String> {
        if self.unary_proofs != self.analyze_unary(m)? {
            return Err("ExpReachingUseMismatch".into());
        }
        Ok(())
    }
    pub(super) fn check_unary_compaction(
        &self,
        next: &mut Self,
        post: &naga::Module,
        remap: &impl Fn(&OwnedExpression) -> Result<Option<OwnedExpression>, String>,
        pre: &naga::Module,
    ) -> Result<(), String> {
        let mut expected = vec![];
        for p in &self.unary_proofs {
            let origin = remap(&p.producer)?;
            for u in &p.uses {
                let mut old = p.producer.clone();
                old.expression = u.edge.producer;
                if let Some(consumer) = remap(&old)? {
                    let origin = origin.as_ref().ok_or("ExpLiveOriginRemoved")?;
                    old.expression = u.edge.operand;
                    let operand = remap(&old)?.ok_or("ExpLiveOperandRemoved")?;
                    if origin.owner != consumer.owner || operand.owner != consumer.owner {
                        return Err("ExpCompactionOwnerMismatch".into());
                    }
                    let mut u = u.clone();
                    u.edge.producer = consumer.expression;
                    u.edge.operand = operand.expression;
                    u.edge.atom.opaque = Some(origin.expression);
                    expected.push((p.source_word, u));
                } else {
                    next.dead_unary_uses.push(DeadUnaryUse {
                        proof: p.clone(),
                        usage: u.clone(),
                        removed_at_revision: self.revision + 1,
                        pre_module: module_identity(pre),
                    });
                }
            }
        }
        let actual = next
            .analyze_unary(post)?
            .into_iter()
            .flat_map(|p| p.uses.into_iter().map(move |u| (p.source_word, u)))
            .collect::<Vec<_>>();
        if actual != expected {
            return Err("ExpCompactionUseMismatch".into());
        }
        Ok(())
    }
}

