//! Bounded bit-exact operations: direct temp-to-output and temp-to-temp copies,
//! raw conditional moves, and SM5 input shifts.
//! These operations require uint32 proofs, never floating arithmetic controls.
use super::*;
use dxbc_reader::decode::{Register, Selection};
fn source(r: &SourceInstruction, name: &str, arity: usize) -> Result<u8, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "BitExactRawDecodeMismatch")?;
    let mut actual = decoded.instructions.first().ok_or("BitExactRawDecodeMismatch")?.clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}")
        || crate::source_hash(&r.words.iter().flat_map(|w|w.to_le_bytes()).collect::<Vec<_>>()) != r.digest {
        return Err("BitExactRawDecodeMismatch".into());
    }
    if i.name() != name || i.operands.len() != arity + 1 || i.precise_mask() == 0
        || r.flags.len() != 1 || r.flags[0] & 1 == 0 || r.reason != PrecisionReason::ExplicitMask {
        return Err("BitExactSourcePolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0 || !i.extensions.is_empty() || i.saturate
        || i.operands.iter().any(|o| o.modifier != 0 || o.precision != 0 || o.non_uniform
            || o.indices.iter().any(|i|i.relative.is_some())) {
        return Err("BitExactModifierOrPrecisionUnsupported".into());
    }
    let Selection::Mask(mask) = i.operands[0].selection else { return Err("BitExactMaskUnsupported".into()) };
    let lanes=(0..4).filter(|l|mask&(1<<l)!=0).collect::<Vec<u8>>();
    if mask == 0 || mask & !15 != 0 || i.precise_mask() & !mask != 0 || r.destinations.len()!=1
        || r.destinations[0].ordinal!=0 || r.destinations[0].null || r.destinations[0].mask!=mask
        || r.destinations[0].lanes!=lanes {
        return Err("BitExactDestinationInventoryMismatch".into());
    }
    Ok(mask)
}
pub fn register_copy_lanes(r: &SourceInstruction) -> Result<Vec<u8>, String> {
    let mask=source(r,"mov",1)?;let i=&r.instruction;
    // A precise temp-to-temp mov is the same raw copy (D3D11.3 3.1.3.2: a mov "must not
    // alter data at all"; Learn mov: "The absence of modifiers just moves data without
    // altering bits"), so the destination may be an output or a temp register.
    if !matches!(i.operands[0].register, Register::Output | Register::Temp) || i.operands[1].register!=Register::Temp
        || i.operands.iter().any(|o|o.indices.len()!=1 || o.components!=4) {
        return Err("BitExactCopyOperandDomainUnsupported".into());
    }
    selected(&i.operands[1].selection,mask)
}
fn selected(s:&Selection, mask:u8)->Result<Vec<u8>,String>{
    (0..4).filter(|l|mask&(1<<l)!=0).map(|l|match s {
        Selection::Scalar(c) if *c<4=>Ok(*c),
        Selection::Swizzle(sw) if sw[l]<4=>Ok(sw[l]),
        _=>Err("BitExactSelectionUnsupported".into()),
    }).collect()
}
/// The tokens of the precise wrist-family `ishl r0.w, r0.w, l(4)` and their source digest.
const WRIST_SHIFT644: [u32; 7] = [121634857, 1048706, 0, 1048634, 0, 16385, 4];
const WRIST_SHIFT_DIGEST644: &str = "sha256:276819d86bbfaeda2d03f9678cf7be79f63c364ababd6653cc4c6c5e4eb1c37a";
pub fn logical_shift_lanes(r:&SourceInstruction)->Result<Vec<u8>,String>{
    let mask=source(r,"ishl",2)?;let i=&r.instruction;
    // Wrist-family byte address: r0.w = r0.w << 4, kept in the uint domain. Admitted by its
    // exact tokens at any word position (replaces a per-shader word table).
    let wrist = r.words==WRIST_SHIFT644 && r.digest==WRIST_SHIFT_DIGEST644
        && mask==8 && i.operands[1].register==Register::Temp
        && i.operands[2].components==1 && i.operands[2].selection==Selection::Scalar(0);
    if i.operands[0].register!=Register::Temp || !(i.operands[1].register==Register::Input || wrist)
        || i.operands[..2].iter().any(|o|o.indices.len()!=1 || o.components!=4)
        || i.operands[2].register!=Register::Immediate || !i.operands[2].indices.is_empty()
        || !((i.operands[2].components==4 && matches!(i.operands[2].selection,Selection::Mask(_))) || wrist) {
        return Err("BitExactShiftOperandDomainUnsupported".into());
    }
    selected(&i.operands[1].selection,mask)
}
pub(super) fn check_register_copy(m:&naga::Module,f:&naga::Function,b:&ProducerBinding,r:&SourceInstruction)->Result<bool,String>{
    let lanes=register_copy_lanes(r)?;
    if b.operands.len()!=1 || b.input_widths[0].get()!=4 || b.width.get() as usize!=lanes.len() || b.controlled {return Ok(false)}
    let base=b.operands[0].expression;
    let Expression::Load{pointer}=f.expressions[base] else {return Ok(false)};
    let Expression::LocalVariable(local)=f.expressions[pointer] else {return Ok(false)};
    if f.local_variables[local].name.as_deref()!=Some(format!("r{}",r.instruction.operands[1].indices[0].base).as_str()){return Ok(false)}
    let picked=match &f.expressions[b.producer.expression]{
        Expression::Swizzle{size,vector,pattern}=>*vector==base && *size as usize==lanes.len() && pattern[..lanes.len()].iter().map(|c|*c as u8).eq(lanes),
        Expression::AccessIndex{base:vector,index}=>*vector==base && lanes==[*index as u8],
        _=>false,
    };
    // This is an ordinary typed uint vector, including the source load.
    check_binding_type(m,f,b)?;Ok(picked)
}
pub(super) fn check_logical_shift(f:&naga::Function,b:&ProducerBinding,r:&SourceInstruction)->Result<bool,String>{
    let lanes=logical_shift_lanes(r)?;
    if b.controlled || b.operands.len()!=2{return Ok(false)}
    let Expression::Binary{op:naga::BinaryOperator::And,left,right}=f.expressions[b.operands[1].expression] else {return Ok(false)};
    fn thirty_one(f:&naga::Function,h:Handle<Expression>)->bool {match f.expressions[h]{
        Expression::Literal(naga::Literal::U32(31))=>true,
        Expression::Splat{value,..}=>thirty_one(f,value),_=>false,
    }}
    let input=b.operands[0].expression;
    let base=match &f.expressions[input]{
        Expression::Swizzle{size,vector,pattern} if *size as usize==lanes.len() && pattern[..lanes.len()].iter().map(|c|*c as u8).eq(lanes.iter().copied())=>*vector,
        Expression::AccessIndex{base,index} if lanes==[*index as u8]=>*base,
        _=>return Ok(false),
    };
    let Expression::Load{pointer}=f.expressions[base] else{return Ok(false)};
    let Expression::LocalVariable(local)=f.expressions[pointer] else{return Ok(false)};
    let prefix=if r.instruction.operands[1].register==dxbc_reader::decode::Register::Temp{"r"}else{"v"};
    if f.local_variables[local].name.as_deref()!=Some(format!("{prefix}{}",r.instruction.operands[1].indices[0].base).as_str()){return Ok(false)}
    fn immediate(f:&naga::Function,h:Handle<Expression>)->Option<Vec<u32>>{match &f.expressions[h]{
        Expression::Literal(naga::Literal::U32(x))=>Some(vec![*x]),
        Expression::Compose{components,..}=>components.iter().map(|h|match f.expressions[*h]{Expression::Literal(naga::Literal::U32(x))=>Some(x),_=>None}).collect(),
        _=>None,
    }}
    let expected=r.destinations[0].lanes.iter().map(|l|r.instruction.operands[2].immediate[*l as usize]).collect::<Vec<_>>();
    Ok(thirty_one(f,right) && immediate(f,left)==Some(expected))
}

/// One source of a bit-exact instruction is exactly the original read of `op` at `comps`:
/// a temp register load (named `r{index}`) narrowed by a swizzle/single-lane index (or the whole
/// load for xyzw), optionally reinterpreted by a bitcast to f32 when `float`; or, for an
/// immediate, the u32 literal bits of the selected components.
pub fn register_read865(
    f: &naga::Function,
    h: Handle<Expression>,
    op: &dxbc_reader::decode::Operand,
    comps: &[u8],
    float: bool,
) -> bool {
    if op.register == Register::Immediate {
        if float || !op.indices.is_empty() {
            return false;
        }
        let bits = comps.iter().map(|c| op.immediate.get(*c as usize).copied()).collect::<Option<Vec<_>>>();
        let lit = |h: Handle<Expression>| match f.expressions[h] {
            Expression::Literal(naga::Literal::U32(x)) => Some(x),
            _ => None,
        };
        let got = match &f.expressions[h] {
            Expression::Compose { components, .. } => components.iter().map(|c| lit(*c)).collect(),
            _ => lit(h).map(|x| vec![x]),
        };
        return bits.is_some() && got == bits;
    }
    if op.register != Register::Temp || op.indices.len() != 1 || op.components != 4 {
        return false;
    }
    let h = if float {
        match f.expressions[h] {
            Expression::As { expr, kind: naga::ScalarKind::Float, convert: None } => expr,
            _ => return false,
        }
    } else {
        h
    };
    let load = |h: Handle<Expression>| {
        let Expression::Load { pointer } = f.expressions[h] else { return false };
        let Expression::LocalVariable(local) = f.expressions[pointer] else { return false };
        f.local_variables[local].name.as_deref() == Some(format!("r{}", op.indices[0].base).as_str())
    };
    match &f.expressions[h] {
        Expression::Swizzle { size, vector, pattern } => {
            load(*vector)
                && *size as usize == comps.len()
                && pattern[..comps.len()].iter().map(|c| *c as u8).eq(comps.iter().copied())
        }
        Expression::AccessIndex { base, index } => load(*base) && comps == [*index as u8],
        _ => comps == [0, 1, 2, 3] && load(h),
    }
}

/// Precise `movc` is a conditional raw move ("if the corresponding component in src0 has
/// any bit set, copy from src1, else from src2"; "The absence of modifiers just moves data
/// without altering bits"; D3D11.3 3.1.3.2 exempts conditional moves from denorm flushing).
/// Admitted: temp destination, temp condition, temp or immediate data, no modifier, saturate or
/// minimum precision. Returns the (src0, src1, src2) component of every written lane.
pub fn conditional_move_lanes(r: &SourceInstruction) -> Result<Vec<[u8; 3]>, String> {
    let mask = source(r, "movc", 3)?;
    let i = &r.instruction;
    let temp = |o: &dxbc_reader::decode::Operand| {
        o.register == Register::Temp && o.indices.len() == 1 && o.components == 4
    };
    let immediate = |o: &dxbc_reader::decode::Operand| {
        o.register == Register::Immediate
            && o.indices.is_empty()
            && o.components == 4
            && matches!(o.selection, Selection::Mask(_))
    };
    if !temp(&i.operands[0])
        || !temp(&i.operands[1])
        || !i.operands[2..].iter().all(|o| temp(o) || immediate(o))
    {
        return Err("BitExactConditionalMoveOperandDomainUnsupported".into());
    }
    let pick = |o: &dxbc_reader::decode::Operand, lane: u8| -> Result<u8, String> {
        match o.selection {
            Selection::Mask(_) if o.register == Register::Immediate => Ok(lane),
            Selection::Scalar(c) if c < 4 => Ok(c),
            Selection::Swizzle(sw) if sw[lane as usize] < 4 => Ok(sw[lane as usize]),
            _ => Err("BitExactSelectionUnsupported".into()),
        }
    };
    (0..4u8)
        .filter(|l| mask & (1 << l) != 0)
        .map(|l| Ok([pick(&i.operands[1], l)?, pick(&i.operands[2], l)?, pick(&i.operands[3], l)?]))
        .collect()
}

pub(super) fn check_conditional_move(
    m: &naga::Module,
    f: &naga::Function,
    b: &ProducerBinding,
    r: &SourceInstruction,
) -> Result<bool, String> {
    let lanes = conditional_move_lanes(r)?;
    let n = lanes.len();
    if b.controlled
        || b.role != ProducerRole::ConditionalMove
        || b.kind != crate::build::Kind::U
        || b.operands.len() != 3
        || b.width.get() as usize != n
        || b.input_widths.iter().any(|w| w.get() as usize != n)
        || b.packed_positions != (0..n as u8).collect::<Vec<_>>()
        || b.original_lanes != r.destinations[0].lanes
    {
        return Ok(false);
    }
    let Expression::Select { condition, accept, reject } = f.expressions[b.producer.expression] else {
        return Ok(false);
    };
    let Expression::Binary { op: naga::BinaryOperator::NotEqual, left, right } = f.expressions[condition]
    else {
        return Ok(false);
    };
    fn zero(f: &naga::Function, h: Handle<Expression>) -> bool {
        match f.expressions[h] {
            Expression::Literal(naga::Literal::U32(0)) => true,
            Expression::Splat { value, .. } => zero(f, value),
            _ => false,
        }
    }
    let ops = &r.instruction.operands;
    let comps = |k: usize| lanes.iter().map(|l| l[k]).collect::<Vec<_>>();
    let shaped = left == b.operands[0].expression
        && zero(f, right)
        && accept == b.operands[1].expression
        && reject == b.operands[2].expression
        && (0..3).all(|k| register_read865(f, b.operands[k].expression, &ops[k + 1], &comps(k), false));
    check_binding_type(m, f, b)?;
    Ok(shaped)
}

//! Raw SRV read proof for the precise `ld_raw` reads of the vs_popcorn_uber_mesh_v family.
//! Admission is structural: the exact form below is admitted at any word of any source
//! (it replaces earlier per-source hash/word tables):
//! - exactly one raw/structured resource declaration, `dcl_resource_raw t4` (tokens
//!   [50331809,1077248,4]);
//! - each precise `ld_raw`: extension tokens [2147484354,1677699], no modifier, saturate,
//!   precision or relative index, a temp scalar byte address, and either a temp `.xyzw`
//!   destination reading `t4.xyzw` or a temp `.w` destination reading `t4.x` (the scalar form).
//! Rationale: every load of the vs_popcorn_uber_mesh_v family sources and of the effect VS
//! e98c2fa1 / 6a3ac76c has exactly this form. The existing uint32 graph is checked; no address,
//! read, or zero arm is replaced.
use super::*;
use dxbc_reader::decode::{Declared, Register, Selection};
/// The only admitted raw declaration: `dcl_resource_raw t4`.
const RAW_DECLARATION582: [u32; 3] = [50331809, 1077248, 4];
/// Whether a precise `ld_raw` record has the scalar `.w <- t4.x` form (destination mask `.w`).
/// [`raw_load_source582`] checks the rest of that form.
pub fn raw_scalar582(r: &SourceInstruction) -> bool {
    matches!(r.instruction.operands.first().map(|o| &o.selection), Some(Selection::Mask(8)))
}
#[derive(Clone, Debug)]
pub struct RawDeclaration582 { pub word: usize, pub words: Vec<u32>, pub source_sha: String }
pub fn raw_load_source582(r: &SourceInstruction) -> Result<(), String> {
    let i=&r.instruction;
