    let mask = if scalar {8} else {15};
    let mut words=vec![0x10050,(r.words.len()+2)as u32];words.extend(&r.words);
    let decoded=dxbc_reader::decode::decode(&words).map_err(|_|"Raw582SourceDecode")?;
    let mut actual=decoded.instructions.first().ok_or("Raw582SourceDecode")?.clone();actual.word=i.word;
