//! Source precise `round_ni` (D3D round toward -inf, `floor`) domain. No arithmetic evaluation.
//!
//! Admitted: every written lane precise, no saturate/modifier/minimum precision/extension,
//! a temp destination, and a temp or immediate source. Anything else is refused, never relaxed.
use super::*;
use dxbc_reader::decode::{Register, Selection};

/// One admitted lane: (destination lane, selected source component).
pub type RoundNiLane = (u8, u8);

/// Re-decode the retained raw words and check the admitted `round_ni` shape.
pub fn round_ni_lanes(r: &SourceInstruction) -> Result<Vec<RoundNiLane>, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "RoundNiRawDecodeMismatch")?;
    let mut actual = decoded
        .instructions
        .first()
        .ok_or("RoundNiRawDecodeMismatch")?
        .clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("RoundNiRawDecodeMismatch".into());
    }
    if i.name() != "round_ni"
        || i.operands.len() != 2
        || r.flags.len() != 1
        || r.flags[0] & 1 == 0
        || r.reason != PrecisionReason::ExplicitMask
    {
        return Err("RoundNiPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| {
            o.modifier != 0
                || o.precision != 0
                || o.non_uniform
                || o.indices.iter().any(|x| x.relative.is_some())
        })
    {
        return Err("RoundNiModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let s = &i.operands[1];
    let Selection::Mask(mask) = d.selection else {
        return Err("RoundNiDestinationUnsupported".into());
    };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("RoundNiDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        // A partially precise write would need an ordinary/controlled split; not admitted.
        return Err("RoundNiPartialPrecisionUnsupported".into());
    }
    if !((s.register == Register::Temp && s.indices.len() == 1)
        || (s.register == Register::Immediate && s.indices.is_empty()))
    {
        return Err("RoundNiInputDomainUnsupported".into());
    }
    let lanes: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    if r.destinations.len() != 1
        || r.destinations[0].ordinal != 0
        || r.destinations[0].null
        || r.destinations[0].mask != mask
        || r.destinations[0].lanes != lanes
    {
        return Err("RoundNiDestinationInventoryMismatch".into());
    }
    lanes
        .iter()
        .map(|&lane| {
            let selected = match s.selection {
                Selection::Mask(_) if s.register == Register::Immediate => lane,
                Selection::Scalar(c) => c,
                Selection::Swizzle(sw) => sw[lane as usize],
                _ => return Err("RoundNiSelectionUnsupported".to_string()),
            };
            if selected > 3
                || (s.register == Register::Immediate && s.immediate.get(selected as usize).is_none())
            {
                return Err("RoundNiSelectionUnsupported".into());
            }
            Ok((lane, selected))
        })
        .collect()
}

/// The receipt binding for an admitted source `round_ni`: one controlled f32 Floor over all lanes.
pub(super) fn check_round_ni(
    module: &naga::Module,
    f: &naga::Function,
    b: &ProducerBinding,
    r: &SourceInstruction,
) -> Result<bool, String> {
    let lanes = round_ni_lanes(r)?;
    let Expression::Math {
        fun: naga::MathFunction::Floor,
        arg,
        arg1: None,
        arg2: None,
        arg3: None,
    } = f.expressions[b.producer.expression]
    else {
        return Ok(false);
    };
    let positions: Vec<u8> = (0..lanes.len() as u8).collect();
    if !b.controlled
        || b.role != ProducerRole::RoundNi
        || b.kind != crate::build::Kind::F
        || b.scalar_bytes != 4
        || b.destination != 0
        || b.operands.len() != 1
        || b.operands[0].expression != arg
        || b.width.get() as usize != lanes.len()
        || b.input_widths.iter().map(|w| w.get()).collect::<Vec<_>>() != [lanes.len() as u8]
        || b.original_lanes != lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != positions
    {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}

//! Float source-operand modifiers on precise add/mul/dp. No arithmetic evaluation.
//!
//! D3D11.3 Functional Specification 22.18: for floating point instructions `_abs` forces the
//! sign positive and negate flips the sign, including on INF; NaN stays NaN with an undefined
//! bit pattern; `-x_abs` is abs first, then negate. These are sign-only operations applied to the
//! source operand before the instruction, so they are carried as explicit `Abs`/`Negate` operand
//! expressions in front of the controlled producer, never folded into it. Integer negate (2's
//! complement), `_sat` and minimum precision are not covered here and stay refused.
use super::*;

/// D3D source modifier codes: none, negate, abs, abs-then-negate.
pub const MODIFIER_NONE: u32 = 0;
pub const MODIFIER_NEG: u32 = 1;
pub const MODIFIER_ABS: u32 = 2;
pub const MODIFIER_ABS_NEG: u32 = 3;

/// Modifiers of the source operands (in source order) of an admitted precise float instruction.
/// Destinations never carry a modifier; integer instructions admit none.
pub fn source_modifiers(r: &SourceInstruction) -> Result<Vec<u32>, &'static str> {
    let i = &r.instruction;
    let (destinations, sources) = i
        .destinations_and_sources()
        .ok_or("PreciseCompoundModifierUnresolved")?;
    if destinations.iter().any(|d| d.modifier != 0) {
        return Err("PreciseCompoundModifierUnresolved");
    }
    let float = matches!(i.name(), "add" | "mul" | "dp2" | "dp3" | "dp4");
    let modifiers: Vec<u32> = sources.iter().map(|s| s.modifier as u32).collect();
    if modifiers.iter().all(|m| *m == MODIFIER_NONE) {
        return Ok(modifiers);
    }
    if !float || modifiers.iter().any(|m| *m > MODIFIER_ABS_NEG) {
        return Err("PreciseCompoundModifierUnresolved");
    }
    // Re-decode the retained raw words: the admitted modifier is the source token's, not a copy.
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded =
        dxbc_reader::decode::decode(&words).map_err(|_| "PreciseSourceModifierDecodeMismatch")?;
    let mut actual = decoded
        .instructions
        .first()
        .ok_or("PreciseSourceModifierDecodeMismatch")?
        .clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("PreciseSourceModifierDecodeMismatch");
    }
    Ok(modifiers)
}

/// Peel at most one lane selection that the lifter adds for a partially precise write
/// (a swizzle, or a single-lane index of a vector value).
fn selected(f: &naga::Function, h: Handle<Expression>) -> Handle<Expression> {
    match f.expressions[h] {
        Expression::Swizzle { vector, .. } => vector,
        Expression::AccessIndex { base, .. } => base,
        _ => h,
    }
}

/// The exact modifier chain an operand expression carries, as a D3D modifier code.
pub fn operand_modifier(f: &naga::Function, operand: Handle<Expression>) -> u32 {
    let neg = |h| match f.expressions[h] {
        Expression::Unary { op: naga::UnaryOperator::Negate, expr } => Some(expr),
        _ => None,
    };
    let abs = |h| {
        matches!(
            f.expressions[h],
            Expression::Math { fun: naga::MathFunction::Abs, arg1: None, arg2: None, arg3: None, .. }
        )
    };
    let h = selected(f, operand);
    match neg(h) {
        Some(inner) if abs(inner) => MODIFIER_ABS_NEG,
        Some(inner) if neg(inner).is_some() => u32::MAX, // never produced by a single modifier
        Some(_) => MODIFIER_NEG,
        None if abs(h) => MODIFIER_ABS,
        None => MODIFIER_NONE,
    }
}

/// Every bound operand carries exactly its source operand's modifier and stays the same f32 type.
pub(super) fn check_source_modifiers(
    module: &naga::Module,
    f: &naga::Function,
    b: &ProducerBinding,
    r: &SourceInstruction,
) -> Result<bool, String> {
    let modifiers = source_modifiers(r)?;
    // Low multiply binds its two sources too (integer: always unmodified).
    let sources = modifiers;
    if sources.len() != b.operands.len() {
        return Ok(false);
    }
    let mut t = naga::front::Typifier::new();
    let ctx = naga::proc::ResolveContext::with_locals(module, &f.local_variables, &f.arguments);
    for (k, a) in b.operands.iter().enumerate() {
        if operand_modifier(f, a.expression) != sources[k] {
            return Ok(false);
        }
        if sources[k] == MODIFIER_NONE {
            continue;
        }
        // The modifier chain is f32 and type-preserving from the register value to the operand.
        let h = selected(f, a.expression);
        let mut chain = vec![h];
        if let Expression::Unary { expr, .. } = f.expressions[h] {
            chain.push(expr);
        }
        if let Some(&last) = chain.last() {
            if let Expression::Math { arg, .. } = f.expressions[last] {
                chain.push(arg);
            }
        }
        let mut ty = None;
        for h in chain {
            t.grow(h, &f.expressions, &ctx).map_err(|e| e.to_string())?;
            let inner = t.get(h, &module.types).clone();
            let f32 = matches!(
                inner,
                naga::TypeInner::Scalar(naga::Scalar::F32)
                    | naga::TypeInner::Vector { scalar: naga::Scalar::F32, .. }
            );
            if !f32 || ty.as_ref().is_some_and(|t| *t != inner) {
                return Ok(false);
            }
            ty = Some(inner);
        }
    }
    Ok(true)
}

//! Source precise `lt` (D3D float less-than) domain and producer shape.
//! No arithmetic evaluation.
//!
//! D3D semantics (Microsoft Learn "lt (sm4 - asm)"; D3D11.3 Functional Specification 3.1.3.1
//! and 3.1.3.2): per component, the result is 0xFFFFFFFF where `src0 < src1` holds and 0
//! otherwise; "Denorms are flushed before comparison; original source registers are
//! untouched"; "+0 equals -0"; "Comparison with NaN returns false".
//!
//! Admitted lowering, per lane, built by the lifter and re-checked here:
//!
//! ```text
//! bits    = bitcast<u32>(x)
//! flushed = bitcast<f32>(select(bits & 0x80000000, bits, (bits & 0x7f800000) != 0))
//!           -- written as Select { condition: (bits & 0x7f800000) == 0,
//!                                  accept: bits & 0x80000000, reject: bits }
//! less    = flushed(src0) < flushed(src1)      -- controlled LessF32NoRefactoringV1
//! result  = select(0xFFFFFFFF, 0, less)        -- the D3D mask
//! ```
//!
//! The flush is integer-only (exact on every target, independent of the device FP32 denormal
//! mode); it maps every denormal to the zero of the same sign and leaves every other bit
//! pattern (zeros, normals, infinities, NaNs) unchanged. The ordered `<` then never sees a
//! denormal. Admitted: every written lane precise, temp destination, temp sources, no
//! modifier, saturate, minimum precision, extension or relative index. Anything else refuses.
use super::*;
use dxbc_reader::decode::{Register, Selection};

/// One admitted lane: (destination lane, src0 component, src1 component).
pub type LessLane = (u8, u8, u8);

pub const LESS_EXPONENT_MASK: u32 = 0x7f80_0000;
pub const LESS_SIGN_MASK: u32 = 0x8000_0000;

/// Re-decode the retained raw words and check the admitted precise `lt` shape.
pub fn less_lanes(r: &SourceInstruction) -> Result<Vec<LessLane>, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "LessRawDecodeMismatch")?;
    let mut actual = decoded
        .instructions
        .first()
        .ok_or("LessRawDecodeMismatch")?
        .clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("LessRawDecodeMismatch".into());
    }
    if i.name() != "lt"
        || i.operands.len() != 3
        || r.flags.len() != 1
        || r.flags[0] & 1 == 0
        || r.reason != PrecisionReason::ExplicitMask
    {
        return Err("LessPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| {
            o.modifier != 0
                || o.precision != 0
                || o.non_uniform
                || o.indices.iter().any(|x| x.relative.is_some())
        })
    {
        return Err("LessModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let Selection::Mask(mask) = d.selection else {
        return Err("LessDestinationUnsupported".into());
    };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("LessDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        return Err("LessPartialPrecisionUnsupported".into());
    }
    if i.operands[1..]
        .iter()
        .any(|s| s.register != Register::Temp || s.indices.len() != 1 || s.components != 4)
    {
        return Err("LessInputDomainUnsupported".into());
    }
    let lanes: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    if r.destinations.len() != 1
        || r.destinations[0].ordinal != 0
        || r.destinations[0].null
        || r.destinations[0].mask != mask
        || r.destinations[0].lanes != lanes
    {
        return Err("LessDestinationInventoryMismatch".into());
    }
    let pick = |s: &dxbc_reader::decode::Operand, lane: u8| -> Result<u8, String> {
        let c = match s.selection {
            Selection::Scalar(c) => c,
            Selection::Swizzle(sw) => sw[lane as usize],
            _ => return Err("LessSelectionUnsupported".into()),
        };
        if c > 3 {
            return Err("LessSelectionUnsupported".into());
        }
        Ok(c)
    };
    lanes
        .iter()
        .map(|&lane| Ok((lane, pick(&i.operands[1], lane)?, pick(&i.operands[2], lane)?)))
        .collect()
}

/// u32 literal lanes of `h`: a literal, or a splat of one.
fn u32_literal(f: &naga::Function, h: Handle<Expression>) -> Option<u32> {
    match f.expressions[h] {
        Expression::Literal(naga::Literal::U32(v)) => Some(v),
        Expression::Splat { value, .. } => u32_literal(f, value),
        _ => None,
    }
}

/// If `h` is exactly the admitted integer denormal flush of some f32 value, return that value.
pub fn flushed_input(f: &naga::Function, h: Handle<Expression>) -> Option<Handle<Expression>> {
    let Expression::As { expr: select, kind: naga::ScalarKind::Float, convert: None } = f.expressions[h]
    else {
        return None;
    };
    let Expression::Select { condition, accept, reject: bits } = f.expressions[select] else {
        return None;
    };
    // 865d (R3): the flushed bits are the raw u32 register read itself (no float reinterpretation).
    let x = bits;
    let Expression::Binary { op: naga::BinaryOperator::Equal, left: exponent, right: zero } =
        f.expressions[condition]
    else {
        return None;
    };
    let Expression::Binary { op: naga::BinaryOperator::And, left: b1, right: em } = f.expressions[exponent]
    else {
        return None;
    };
    let Expression::Binary { op: naga::BinaryOperator::And, left: b2, right: sm } = f.expressions[accept]
    else {
        return None;
    };
    (b1 == bits
        && b2 == bits
        && u32_literal(f, em) == Some(LESS_EXPONENT_MASK)
        && u32_literal(f, sm) == Some(LESS_SIGN_MASK)
        && u32_literal(f, zero) == Some(0))
    .then_some(x)
}

/// Every Select whose condition is `producer` must be the exact D3D mask, and there is one.
pub fn mask_consumers(f: &naga::Function, producer: Handle<Expression>) -> usize {
    let mut good = 0;
    for (_, e) in f.expressions.iter() {
        match *e {
            Expression::Select { condition, accept, reject } if condition == producer => {
                if u32_literal(f, accept) == Some(u32::MAX) && u32_literal(f, reject) == Some(0) {
                    good += 1;
                } else {
                    return usize::MAX;
                }
            }
            Expression::Select { accept, reject, .. } if accept == producer || reject == producer => {
                return usize::MAX
            }
            Expression::Binary { left, right, .. } if left == producer || right == producer => {
                return usize::MAX
            }
            Expression::Unary { expr, .. }
            | Expression::As { expr, .. }
            | Expression::Relational { argument: expr, .. }
            | Expression::Swizzle { vector: expr, .. }
            | Expression::AccessIndex { base: expr, .. }
            | Expression::Splat { value: expr, .. }
                if expr == producer =>
            {
                return usize::MAX
            }
            Expression::Compose { ref components, .. } if components.contains(&producer) => {
                return usize::MAX
            }
            _ => {}
        }
    }
    good
}

/// The receipt binding for an admitted source `lt`: one controlled f32 Less over all lanes, with
/// flushed operands, consumed only as the D3D mask.
pub(super) fn check_less(
    module: &naga::Module,
    f: &naga::Function,
    b: &ProducerBinding,
    r: &SourceInstruction,
) -> Result<bool, String> {
    let lanes = less_lanes(r)?;
    let Expression::Binary { op: naga::BinaryOperator::Less, left, right } =
        f.expressions[b.producer.expression]
    else {
        return Ok(false);
    };
    let positions: Vec<u8> = (0..lanes.len() as u8).collect();
    if !b.controlled
        || b.role != ProducerRole::CompareLess
        || b.kind != crate::build::Kind::B
        || b.scalar_bytes != 4
        || b.destination != 0
        || b.operands.len() != 2
        || b.operands[0].expression != left
        || b.operands[1].expression != right
        || flushed_input(f, left).is_none()
        || flushed_input(f, right).is_none()
        || b.width.get() as usize != lanes.len()
        || b.input_widths.iter().map(|w| w.get()).collect::<Vec<_>>() != [lanes.len() as u8; 2]
        || b.original_lanes != lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != positions
        || mask_consumers(f, b.producer.expression) != 1
        || !(0..2).all(|k| {
            let comps = lanes.iter().map(|l| if k == 0 { l.1 } else { l.2 }).collect::<Vec<_>>();
            flushed_input(f, b.operands[k].expression).is_some_and(|x| {
                register_read865(f, x, &r.instruction.operands[k + 1], &comps, false)
            })
        })
    {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}

//! Source precise `frc` domain and producer shape. No arithmetic evaluation.
//!
//! Normative evidence is a measurement, not a document reading: the D3D12 WARP adapter
//! (Microsoft WARP, the Basic Render Driver) running fxc `frc [precise]`
//! (DXBC cs_5_0) over all 2^32 input bit patterns matches, with zero mismatches, exactly:
//!
//! ```text
//! special  = (bits & 0x7f800000) == 0x7f800000          // +-Inf or NaN
//! flushed  = (bits & 0x7f800000) == 0 ? bits & 0x80000000 : bits   // denormal -> signed zero
//! x        = asfloat(flushed)
//! d        = x - floor(x)                               // f32, round to nearest even
//! clamped  = asuint(d) == 0x3f800000 ? 0x3f7fffff : asuint(d)
//! nan      = (bits & 0x007fffff) != 0 ? bits | 0x00400000 : 0xffc00000
//! result   = special ? nan : clamped
//! ```
//!
//! Learn's formula `src0 - round_ni(src0)` alone gives 1.0 for 859,832,320 negative inputs
//! (where 1 + x rounds up); WARP returns 0x3f7fffff there, the table's `[+0 to 1)`. The lifter
//! builds exactly this graph: a controlled f32 Floor (`FloorF32NoRefactoringV1`) and a controlled
//! f32 Subtract (`NoContraction`); everything else is u32 bit selection, exact on every target.
//! Admitted: every written lane precise, temp destination and source, no modifier, saturate,
//! minimum precision, extension or relative index.
use super::*;
use dxbc_reader::decode::{Register, Selection};

pub const FRAC_EXPONENT_MASK: u32 = 0x7f80_0000;
pub const FRAC_SIGN_MASK: u32 = 0x8000_0000;
pub const FRAC_MANTISSA_MASK: u32 = 0x007f_ffff;
pub const FRAC_QUIET_BIT: u32 = 0x0040_0000;
pub const FRAC_ONE: u32 = 0x3f80_0000;
pub const FRAC_BELOW_ONE: u32 = 0x3f7f_ffff;
pub const FRAC_INFINITY_NAN: u32 = 0xffc0_0000;

/// One admitted lane: (destination lane, source component).
pub type FracLane = (u8, u8);

/// Re-decode the retained raw words and check the admitted precise `frc` shape.
pub fn frac_lanes(r: &SourceInstruction) -> Result<Vec<FracLane>, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "FracRawDecodeMismatch")?;
    let mut actual = decoded.instructions.first().ok_or("FracRawDecodeMismatch")?.clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("FracRawDecodeMismatch".into());
    }
    if i.name() != "frc"
        || i.operands.len() != 2
        || r.flags.len() != 1
        || r.flags[0] & 1 == 0
        || r.reason != PrecisionReason::ExplicitMask
    {
        return Err("FracPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| {
            o.modifier != 0 || o.precision != 0 || o.non_uniform || o.indices.iter().any(|x| x.relative.is_some())
        })
    {
        return Err("FracModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let s = &i.operands[1];
    let Selection::Mask(mask) = d.selection else {
        return Err("FracDestinationUnsupported".into());
    };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("FracDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        return Err("FracPartialPrecisionUnsupported".into());
    }
    if s.register != Register::Temp || s.indices.len() != 1 || s.components != 4 {
        return Err("FracInputDomainUnsupported".into());
    }
    let lanes: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    if r.destinations.len() != 1
        || r.destinations[0].ordinal != 0
        || r.destinations[0].null
        || r.destinations[0].mask != mask
        || r.destinations[0].lanes != lanes
    {
        return Err("FracDestinationInventoryMismatch".into());
    }
    lanes
        .iter()
        .map(|&lane| {
            let c = match s.selection {
                Selection::Scalar(c) => c,
                Selection::Swizzle(sw) => sw[lane as usize],
                _ => return Err("FracSelectionUnsupported".to_string()),
            };
            if c > 3 {
                return Err("FracSelectionUnsupported".into());
            }
            Ok((lane, c))
        })
        .collect()
}

fn lit(f: &naga::Function, h: Handle<Expression>) -> Option<u32> {
    match f.expressions[h] {
        Expression::Literal(naga::Literal::U32(v)) => Some(v),
        Expression::Splat { value, .. } => lit(f, value),
        _ => None,
    }
}

/// Number of expressions (and Store/Return statements, recursively) that use `h` as an operand.
pub fn uses865(f: &naga::Function, h: Handle<Expression>) -> usize {
    let mut n = 0;
    for (_, e) in f.expressions.iter() {
        n += match *e {
            Expression::Select { condition, accept, reject } => {
                [condition, accept, reject].iter().filter(|x| **x == h).count()
            }
            Expression::Binary { left, right, .. } => [left, right].iter().filter(|x| **x == h).count(),
            Expression::Unary { expr, .. }
            | Expression::As { expr, .. }
            | Expression::Relational { argument: expr, .. }
            | Expression::Swizzle { vector: expr, .. }
            | Expression::AccessIndex { base: expr, .. }
            | Expression::Splat { value: expr, .. }
            | Expression::Load { pointer: expr } => usize::from(expr == h),
            Expression::Access { base, index } => [base, index].iter().filter(|x| **x == h).count(),
            Expression::Compose { ref components, .. } => components.iter().filter(|x| **x == h).count(),
            Expression::Math { arg, arg1, arg2, arg3, .. } => {
                usize::from(arg == h) + [arg1, arg2, arg3].iter().filter(|x| **x == Some(h)).count()
            }
            _ => 0,
        };
    }
    fn block(b: &naga::Block, h: Handle<Expression>) -> usize {
        b.iter()
            .map(|s| match s {
                naga::Statement::Store { pointer, value } => usize::from(*pointer == h) + usize::from(*value == h),
                naga::Statement::Return { value } => usize::from(*value == Some(h)),
                naga::Statement::If { condition, accept, reject } => {
                    usize::from(*condition == h) + block(accept, h) + block(reject, h)
                }
                naga::Statement::Block(b) => block(b, h),
                _ => 0,
            })
            .sum()
    }
    n + block(&f.body, h)
}

/// The admitted per-lane graph around a controlled Subtract `d = x - floor(x)`: returns the source
/// value (before the flush) and the final u32 result if every node is exactly as documented and
/// the float result `d` reaches nothing but the clamp.
pub fn frac_graph(f: &naga::Function, d: Handle<Expression>) -> Option<(Handle<Expression>, Handle<Expression>)> {
    let Expression::Binary { op: naga::BinaryOperator::Subtract, left: x, right: fl } = f.expressions[d] else {
        return None;
    };
    let Expression::Math { fun: naga::MathFunction::Floor, arg, arg1: None, arg2: None, arg3: None } = f.expressions[fl] else {
        return None;
    };
    let source = flushed_input(f, x)?;
    if arg != x {
        return None;
    }
    // bits = As(u32, source): the flush chain's own reinterpretation.
    let Expression::As { expr: select, .. } = f.expressions[x] else { return None };
    let Expression::Select { condition: zero_test, reject: bits, .. } = f.expressions[select] else { return None };
    let Expression::Binary { left: exponent, .. } = f.expressions[zero_test] else { return None };
    // Exactly one use of d: its u32 reinterpretation.
    if uses865(f, d) != 1 || uses865(f, fl) != 1 {
        return None;
    }
    let (db, _) = f
        .expressions
        .iter()
        .find(|(_, e)| matches!(e, Expression::As { expr, kind: naga::ScalarKind::Uint, convert: None } if *expr == d))?;
    // 865d (R3): d is never negative; its sign bit (an NSZ zero-sign flip under R2) is masked off.
    let (db_abs, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Binary { op: naga::BinaryOperator::And, left, right }
        if left == db && lit(f, right) == Some(0x7fff_ffff)))?;
    if uses865(f, db) != 1 {
        return None;
    }
    let db = db_abs;
    // clamped = Select(db == 0x3f800000, 0x3f7fffff, db); db used exactly by that test and select.
    let (clamped, test) = f.expressions.iter().find_map(|(h, e)| match *e {
        Expression::Select { condition, accept, reject } if reject == db => Some((h, (condition, accept))),
        _ => None,
    })?;
    let one_test = matches!(f.expressions[test.0], Expression::Binary { op: naga::BinaryOperator::Equal, left, right }
        if left == db && lit(f, right) == Some(FRAC_ONE));
    if !one_test || lit(f, test.1) != Some(FRAC_BELOW_ONE) || uses865(f, db) != 2 || uses865(f, test.0) != 1 {
        return None;
    }
    // result = Select(special, nan, clamped); clamped used only there.
    let (result, special, nan) = f.expressions.iter().find_map(|(h, e)| match *e {
        Expression::Select { condition, accept, reject } if reject == clamped => Some((h, condition, accept)),
        _ => None,
    })?;
    let special_ok = matches!(f.expressions[special], Expression::Binary { op: naga::BinaryOperator::Equal, left, right }
        if left == exponent && lit(f, right) == Some(FRAC_EXPONENT_MASK));
    let Expression::Select { condition: is_nan, accept: quiet, reject: infinity } = f.expressions[nan] else { return None };
    let nan_ok = matches!(f.expressions[is_nan], Expression::Binary { op: naga::BinaryOperator::NotEqual, left, right }
        if lit(f, right) == Some(0) && matches!(f.expressions[left], Expression::Binary { op: naga::BinaryOperator::And, left: b, right: m }
            if b == bits && lit(f, m) == Some(FRAC_MANTISSA_MASK)))
        && matches!(f.expressions[quiet], Expression::Binary { op: naga::BinaryOperator::InclusiveOr, left, right }
            if left == bits && lit(f, right) == Some(FRAC_QUIET_BIT))
        && lit(f, infinity) == Some(FRAC_INFINITY_NAN);
    (special_ok && nan_ok && uses865(f, clamped) == 1).then_some((source, result))
}

/// Receipt check for both bindings of an admitted precise `frc`.
pub(super) fn check_frac(
    module: &naga::Module,
    f: &naga::Function,
    receipt_bindings: &[ProducerBinding],
    b: &ProducerBinding,
    r: &SourceInstruction,
) -> Result<bool, String> {
    let lanes = frac_lanes(r)?;
    let n = lanes.len();
    let positions: Vec<u8> = (0..n as u8).collect();
    if !b.controlled
        || b.kind != crate::build::Kind::F
        || b.scalar_bytes != 4
        || b.destination != 0
        || b.width.get() as usize != n
        || b.input_widths.iter().any(|w| w.get() as usize != n)
        || b.original_lanes != lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != positions
    {
        return Ok(false);
    }
    let sub = match b.role {
        ProducerRole::FracSubtract => b.producer.expression,
        ProducerRole::FracFloor => {
            let subs: Vec<_> = receipt_bindings
                .iter()
                .filter(|x| x.source_word == b.source_word && x.role == ProducerRole::FracSubtract)
                .collect();
            if subs.len() != 1 || subs[0].operands.get(1).map(|o| o.expression) != Some(b.producer.expression) {
                return Ok(false);
            }
            subs[0].producer.expression
        }
        _ => return Ok(false),
    };
    let Some((source, _)) = frac_graph(f, sub) else { return Ok(false) };
    let Expression::Binary { left: x, right: fl, .. } = f.expressions[sub] else { return Ok(false) };
    let operands_ok = match b.role {
        ProducerRole::FracFloor => b.operands.len() == 1 && b.operands[0].expression == x && b.producer.expression == fl,
        _ => b.operands.len() == 2 && b.operands[0].expression == x && b.operands[1].expression == fl,
    };
    let comps: Vec<u8> = lanes.iter().map(|l| l.1).collect();
    if !operands_ok || !register_read865(f, source, &r.instruction.operands[1], &comps, false) {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}

//! Source precise `max` domain and producer shape. No arithmetic evaluation.
//!
//! D3D11.3 FS 3.1.3.2 leaves two choices open ("min or max operations must flush denorms for
//! comparison, but the result may or may not be denorm flushed"; comparing zeros may depend on
//! operand order) and 3.1.3.1 fixes `max(x, NaN) == max(NaN, x) == x`. The admitted lowering
//! reproduces the measured D3D12 WARP result (Microsoft WARP, fxc cs_5_0
//! `max [precise]`) for DXBC `max dest, src0, src1`:
//!
//! ```text
//! f0, f1 = flush(src0), flush(src1)            // integer: denormal -> zero of the same sign
//! pick   = asfloat(f1) < asfloat(f0) ? f0 : f1 // ordered; ties (+0/-0) and NaN src0 take f1
//! result = (src1 & 0x7fffffff) > 0x7f800000 ? src0 : pick   // NaN src1 returns raw src0
//! ```
//!
//! Evidence: zero mismatches on 1,573,440 measured pairs (24x24 special classes, 1M random,
//! 512K sign/exponent neighbours) and on all 2^32 `max r, x, l(0)` (the original VS shape).
//! The comparison carries `LessF32NoRefactoringV1`; everything else is u32 bit selection.
//! Admitted: every written lane precise, temp destination and src0, temp or immediate src1, no
//! modifier, saturate, minimum precision, extension or relative index.
use super::*;
use dxbc_reader::decode::{Register, Selection};

pub const MAX_MAGNITUDE_MASK: u32 = 0x7fff_ffff;
pub const MAX_INFINITY: u32 = 0x7f80_0000;

/// One admitted lane: (destination lane, src0 component, src1 component).
pub type MaxLane = (u8, u8, u8);

pub fn max_lanes(r: &SourceInstruction) -> Result<Vec<MaxLane>, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "MaxRawDecodeMismatch")?;
    let mut actual = decoded.instructions.first().ok_or("MaxRawDecodeMismatch")?.clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("MaxRawDecodeMismatch".into());
    }
    if i.name() != "max" || i.operands.len() != 3 || r.flags.len() != 1 || r.flags[0] & 1 == 0 || r.reason != PrecisionReason::ExplicitMask {
        return Err("MaxPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| o.modifier != 0 || o.precision != 0 || o.non_uniform || o.indices.iter().any(|x| x.relative.is_some()))
    {
        return Err("MaxModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let Selection::Mask(mask) = d.selection else { return Err("MaxDestinationUnsupported".into()) };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("MaxDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        return Err("MaxPartialPrecisionUnsupported".into());
    }
    let temp = |o: &dxbc_reader::decode::Operand| o.register == Register::Temp && o.indices.len() == 1 && o.components == 4;
    let immediate = |o: &dxbc_reader::decode::Operand| {
        o.register == Register::Immediate && o.indices.is_empty() && o.components == 4 && matches!(o.selection, Selection::Mask(_))
    };
    if !temp(&i.operands[1]) || !(temp(&i.operands[2]) || immediate(&i.operands[2])) {
        return Err("MaxInputDomainUnsupported".into());
    }
    let lanes: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    if r.destinations.len() != 1 || r.destinations[0].ordinal != 0 || r.destinations[0].null || r.destinations[0].mask != mask || r.destinations[0].lanes != lanes {
        return Err("MaxDestinationInventoryMismatch".into());
    }
    let pick = |o: &dxbc_reader::decode::Operand, lane: u8| -> Result<u8, String> {
        match o.selection {
            Selection::Mask(_) if o.register == Register::Immediate => Ok(lane),
            Selection::Scalar(c) if c < 4 => Ok(c),
            Selection::Swizzle(sw) if sw[lane as usize] < 4 => Ok(sw[lane as usize]),
            _ => Err("MaxSelectionUnsupported".into()),
        }
    };
    lanes.iter().map(|&l| Ok((l, pick(&i.operands[1], l)?, pick(&i.operands[2], l)?))).collect()
}

fn lit(f: &naga::Function, h: Handle<Expression>) -> Option<u32> {
    match f.expressions[h] {
        Expression::Literal(naga::Literal::U32(v)) => Some(v),
        Expression::Splat { value, .. } => lit(f, value),
        _ => None,
    }
}

/// `sel` is exactly the integer denormal flush of `bits`; returns `bits`.
pub fn flush_select865(f: &naga::Function, sel: Handle<Expression>) -> Option<Handle<Expression>> {
    let Expression::Select { condition, accept, reject: bits } = f.expressions[sel] else { return None };
    let Expression::Binary { op: naga::BinaryOperator::Equal, left: e, right: zero } = f.expressions[condition] else { return None };
    let and = |h, mask| matches!(f.expressions[h], Expression::Binary { op: naga::BinaryOperator::And, left, right } if left == bits && lit(f, right) == Some(mask));
    (and(e, LESS_EXPONENT_MASK) && and(accept, LESS_SIGN_MASK) && lit(f, zero) == Some(0)).then_some(bits)
}

/// The admitted graph around the controlled `Less(x1, x0)`: returns (src0 bits, src1 bits, result).
pub fn max_graph(f: &naga::Function, less: Handle<Expression>) -> Option<(Handle<Expression>, Handle<Expression>, Handle<Expression>)> {
    let Expression::Binary { op: naga::BinaryOperator::Less, left: x1, right: x0 } = f.expressions[less] else { return None };
    let flushed = |x| match f.expressions[x] {
        Expression::As { expr, kind: naga::ScalarKind::Float, convert: None } => Some(expr),
        _ => None,
    };
    let (s1, s0) = (flushed(x1)?, flushed(x0)?);
    let (b1, b0) = (flush_select865(f, s1)?, flush_select865(f, s0)?);
    if uses865(f, less) != 1 || uses865(f, x0) != 1 || uses865(f, x1) != 1 {
        return None;
    }
    let (pick, _) = f.expressions.iter().find(|(_, e)| matches!(e, Expression::Select { condition, accept, reject } if *condition == less && *accept == s0 && *reject == s1))?;
    if uses865(f, pick) != 1 {
        return None;
    }
    let (result, nan1) = f.expressions.iter().find_map(|(h, e)| match *e {
        Expression::Select { condition, accept, reject } if reject == pick && accept == b0 => Some((h, condition)),
        _ => None,
    })?;
    let nan_ok = matches!(f.expressions[nan1], Expression::Binary { op: naga::BinaryOperator::Greater, left, right }
        if lit(f, right) == Some(MAX_INFINITY)
            && matches!(f.expressions[left], Expression::Binary { op: naga::BinaryOperator::And, left: b, right: m } if b == b1 && lit(f, m) == Some(MAX_MAGNITUDE_MASK)));
    nan_ok.then_some((b0, b1, result))
}

pub(super) fn check_max(module: &naga::Module, f: &naga::Function, b: &ProducerBinding, r: &SourceInstruction) -> Result<bool, String> {
    let lanes = max_lanes(r)?;
    let n = lanes.len();
    let Expression::Binary { op: naga::BinaryOperator::Less, left, right } = f.expressions[b.producer.expression] else { return Ok(false) };
    if !b.controlled
        || b.role != ProducerRole::MaxCompare
        || b.kind != crate::build::Kind::B
        || b.destination != 0
        || b.operands.len() != 2
        || b.operands[0].expression != left
        || b.operands[1].expression != right
        || b.width.get() as usize != n
        || b.input_widths.iter().any(|w| w.get() as usize != n)
        || b.original_lanes != lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != (0..n as u8).collect::<Vec<_>>()
    {
        return Ok(false);
    }
    let Some((b0, b1, _)) = max_graph(f, b.producer.expression) else { return Ok(false) };
    let ops = &r.instruction.operands;
    let c0: Vec<u8> = lanes.iter().map(|l| l.1).collect();
    let c1: Vec<u8> = lanes.iter().map(|l| l.2).collect();
    if !register_read865(f, b0, &ops[1], &c0, false) || !register_read865(f, b1, &ops[2], &c1, false) {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}

//! Tolerance-checked precise transcendental class (`sincos`, `rsq`, `div` by a
//! measured immediate). No arithmetic evaluation.
//!
//! Admission rationale (Microsoft WARP, fxc cs_5_0
//! `sincos/rsq/div [precise]`, all 2^32 inputs; `div` for the original divisor l(30.0)):
//! * documented tolerances (Microsoft Learn instruction reference): sincos "maximum absolute error
//!   is 0.0008 in the interval from -100*Pi to +100*Pi"; rsq "maximum relative error is 2^-21";
//!   div: D3D11.3 FS 3.1.3.2 ("x*(1.0f/y)" with "0.5 ULP for multiply, 1.0 ULP for reciprocal",
//!   or a direct divide of at least that accuracy);
//! * WARP measured: sin 2.674e-5 / cos 2.692e-5 maximum absolute error inside +-100*pi; rsq at most
//!   1 ULP (relative 2^-23.4); x/30 correctly rounded (0 ULP);
//! * WARP edge results, reproduced here exactly in u32 operations (never by the intrinsic):
//!   NaN -> input | 0x00400000; +-Inf -> sin/cos 0xffc00000, rsq +0 / 0xffc00000, div +-Inf;
//!   +-0 and +-denormal -> sin +-0, cos 1.0, rsq +-Inf, div +-0; rsq of a negative normal ->
//!   0xffc00000; a denormal result -> the zero of its sign (none observed for finite inputs).
//!
//! The finite normal path is the intrinsic under `ToleranceF32NoRefactoringV1` (strict
//! FPFastMathMode None, HLSL noinline precise helper). Its accuracy on a consumer is a gate the
//! measured tolerance qualifies; it is not a bit-exact claim.
use super::*;
use dxbc_reader::decode::{Register, Selection};

pub const TOL_EXPONENT_MASK: u32 = 0x7f80_0000;
pub const TOL_SIGN_MASK: u32 = 0x8000_0000;
pub const TOL_MANTISSA_MASK: u32 = 0x007f_ffff;
pub const TOL_QUIET_BIT: u32 = 0x0040_0000;
pub const TOL_INVALID_NAN: u32 = 0xffc0_0000;
/// The only divisor whose `div` was measured exhaustively (original VS SHEX1494 l(30.0)).
pub const TOL_MEASURED_DIVISOR: u32 = 0x41f0_0000;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ToleranceOp {
    Sin,
    Cos,
    Rsq,
    Div,
}
impl ToleranceOp {
    /// (negative, positive) results for a +-0 or +-denormal input.
    pub fn zero(self) -> (u32, u32) {
        match self {
            Self::Sin | Self::Div => (0x8000_0000, 0),
            Self::Cos => (0x3f80_0000, 0x3f80_0000),
            Self::Rsq => (0xff80_0000, 0x7f80_0000),
        }
    }
    /// (negative, positive) results for a +-Inf input.
    pub fn infinity(self) -> (u32, u32) {
        match self {
            Self::Sin | Self::Cos => (TOL_INVALID_NAN, TOL_INVALID_NAN),
            Self::Rsq => (TOL_INVALID_NAN, 0),
            Self::Div => (0xff80_0000, 0x7f80_0000),
        }
    }
    pub fn role(self) -> ProducerRole {
        match self {
            Self::Sin => ProducerRole::ToleranceSin,
            Self::Cos => ProducerRole::ToleranceCos,
            Self::Rsq => ProducerRole::ToleranceRsq,
            Self::Div => ProducerRole::ToleranceDiv,
        }
    }
    pub fn of_role(role: ProducerRole) -> Option<Self> {
        Some(match role {
            ProducerRole::ToleranceSin => Self::Sin,
            ProducerRole::ToleranceCos => Self::Cos,
            ProducerRole::ToleranceRsq => Self::Rsq,
            ProducerRole::ToleranceDiv => Self::Div,
            _ => return None,
        })
    }
}

/// An admitted tolerance instruction: op, destination ordinal, (lane, source component) per lane.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ToleranceLanes {
    pub op: ToleranceOp,
    pub destination: usize,
    pub lanes: Vec<(u8, u8)>,
}

pub fn tolerance_lanes(r: &SourceInstruction) -> Result<ToleranceLanes, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "ToleranceRawDecodeMismatch")?;
    let mut actual = decoded.instructions.first().ok_or("ToleranceRawDecodeMismatch")?.clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("ToleranceRawDecodeMismatch".into());
    }
    let (op, arity) = match i.name() {
        "sincos" => (None, 3),
        "rsq" => (Some(ToleranceOp::Rsq), 2),
        "div" => (Some(ToleranceOp::Div), 3),
        _ => return Err("TolerancePolicyUnsupported".into()),
    };
    if i.operands.len() != arity || r.flags.len() != 1 || r.flags[0] & 1 == 0 || r.reason != PrecisionReason::ExplicitMask {
        return Err("TolerancePolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.saturate
        || i.operands.iter().any(|o| o.modifier != 0 || o.precision != 0 || o.non_uniform || o.indices.iter().any(|x| x.relative.is_some()))
    {
        return Err("ToleranceModifierOrControlUnsupported".into());
    }
    // sincos: exactly one non-null destination (sin = 0, cos = 1).
    let (op, destination) = match op {
        Some(op) => (op, 0),
        None => {
            let live: Vec<usize> = (0..2).filter(|k| i.operands[*k].register != Register::Null).collect();
            if live.len() != 1 {
                return Err("ToleranceDestinationUnsupported".into());
            }
            (if live[0] == 0 { ToleranceOp::Sin } else { ToleranceOp::Cos }, live[0])
        }
    };
    let d = &i.operands[destination];
    let Selection::Mask(mask) = d.selection else { return Err("ToleranceDestinationUnsupported".into()) };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("ToleranceDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        return Err("TolerancePartialPrecisionUnsupported".into());
    }
    let s = &i.operands[if i.name() == "sincos" { 2 } else { 1 }];
    if s.register != Register::Temp || s.indices.len() != 1 || s.components != 4 {
        return Err("ToleranceInputDomainUnsupported".into());
    }
    let lanes_of: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    let dest = r.destinations.iter().find(|x| x.ordinal == destination).ok_or("ToleranceDestinationInventoryMismatch")?;
    if dest.null || dest.mask != mask || dest.lanes != lanes_of || r.destinations.iter().any(|x| x.ordinal != destination && !x.null) {
        return Err("ToleranceDestinationInventoryMismatch".into());
    }
    let pick = |o: &dxbc_reader::decode::Operand, lane: u8| -> Result<u8, String> {
        match o.selection {
            Selection::Scalar(c) if c < 4 => Ok(c),
            Selection::Swizzle(sw) if sw[lane as usize] < 4 => Ok(sw[lane as usize]),
            Selection::Mask(_) if o.register == Register::Immediate => Ok(lane),
            _ => Err("ToleranceSelectionUnsupported".into()),
        }
    };
    if op == ToleranceOp::Div {
        let v = &i.operands[2];
        if v.register != Register::Immediate || !v.indices.is_empty() {
            return Err("ToleranceDivisorDomainUnsupported".into());
        }
        for &l in &lanes_of {
            let c = if v.components == 1 { 0 } else { pick(v, l)? };
            if v.immediate.get(c as usize) != Some(&TOL_MEASURED_DIVISOR) {
                return Err("ToleranceDivisorNotMeasured".into());
            }
        }
    }
    let lanes = lanes_of.iter().map(|&l| Ok((l, pick(s, l)?))).collect::<Result<Vec<_>, String>>()?;
    Ok(ToleranceLanes { op, destination, lanes })
}

fn lit(f: &naga::Function, h: Handle<Expression>) -> Option<u32> {
    match f.expressions[h] {
        Expression::Literal(naga::Literal::U32(v)) => Some(v),
        Expression::Literal(naga::Literal::F32(v)) => Some(v.to_bits()),
        Expression::Splat { value, .. } => lit(f, value),
        Expression::Compose { ref components, .. } => {
            let v = components.iter().map(|c| lit(f, *c)).collect::<Option<Vec<_>>>()?;
            (!v.is_empty() && v.iter().all(|x| *x == v[0])).then(|| v[0])
        }
        _ => None,
    }
}

/// The admitted graph around the controlled producer `r`: returns (source bits, divisor, result).
pub fn tolerance_graph(
    f: &naga::Function,
    op: ToleranceOp,
    r: Handle<Expression>,
) -> Option<(Handle<Expression>, Option<Handle<Expression>>, Handle<Expression>)> {
    let (x, divisor) = match (op, &f.expressions[r]) {
        (ToleranceOp::Sin, &Expression::Math { fun: naga::MathFunction::Sin, arg, arg1: None, .. })
        | (ToleranceOp::Cos, &Expression::Math { fun: naga::MathFunction::Cos, arg, arg1: None, .. })
        | (ToleranceOp::Rsq, &Expression::Math { fun: naga::MathFunction::InverseSqrt, arg, arg1: None, .. }) => (arg, None),
        (ToleranceOp::Div, &Expression::Binary { op: naga::BinaryOperator::Divide, left, right }) => (left, Some(right)),
        _ => return None,
    };
    if divisor.is_some_and(|d| lit(f, d) != Some(TOL_MEASURED_DIVISOR)) {
        return None;
    }
    let Expression::As { expr: bits, kind: naga::ScalarKind::Float, convert: None } = f.expressions[x] else { return None };
    let and = |h: Handle<Expression>, of: Handle<Expression>, mask: u32| {
        matches!(f.expressions[h], Expression::Binary { op: naga::BinaryOperator::And, left, right } if left == of && lit(f, right) == Some(mask))
    };
    let eq = |h: Handle<Expression>, of: &dyn Fn(Handle<Expression>) -> bool, value: u32| {
        matches!(f.expressions[h], Expression::Binary { op: naga::BinaryOperator::Equal, left, right } if of(left) && lit(f, right) == Some(value))
    };
    if uses865(f, r) != 1 || uses865(f, x) != 1 {
        return None;
    }
    let (rb, _) = f.expressions.iter().find(|(_, e)| matches!(e, Expression::As { expr, kind: naga::ScalarKind::Uint, convert: None } if *expr == r))?;
    // rflush = Select((rb & EXP) == 0, rb & SIGN, rb)
    let (rflush, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if reject == rb && and(accept, rb, TOL_SIGN_MASK) && eq(condition, &|h| and(h, rb, TOL_EXPONENT_MASK), 0)))?;
    if uses865(f, rb) != 3 || uses865(f, rflush) != 1 {
        return None;
    }
    let neg_test = |h: Handle<Expression>| matches!(f.expressions[h], Expression::Binary { op: naga::BinaryOperator::NotEqual, left, right }
        if and(left, bits, TOL_SIGN_MASK) && lit(f, right) == Some(0));
    let finite = if op == ToleranceOp::Rsq {
        let (h, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
            if reject == rflush && neg_test(condition) && lit(f, accept) == Some(TOL_INVALID_NAN)))?;
        h
    } else {
        rflush
    };
    let pair = |h: Handle<Expression>, (n, p): (u32, u32)| matches!(f.expressions[h], Expression::Select { condition, accept, reject }
        if neg_test(condition) && lit(f, accept) == Some(n) && lit(f, reject) == Some(p));
    // inner = Select(zden, zero, finite) ; result = Select(special, nan, inner)
    let (inner, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if reject == finite && pair(accept, op.zero()) && eq(condition, &|h| and(h, bits, TOL_EXPONENT_MASK), 0)))?;
    let (result, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if reject == inner && eq(condition, &|h| and(h, bits, TOL_EXPONENT_MASK), TOL_EXPONENT_MASK)
            && matches!(f.expressions[accept], Expression::Select { condition: c, accept: q, reject: inf }
                if matches!(f.expressions[c], Expression::Binary { op: naga::BinaryOperator::NotEqual, left, right }
                    if and(left, bits, TOL_MANTISSA_MASK) && lit(f, right) == Some(0))
                && matches!(f.expressions[q], Expression::Binary { op: naga::BinaryOperator::InclusiveOr, left, right }
                    if left == bits && lit(f, right) == Some(TOL_QUIET_BIT))
                && pair(inf, op.infinity()))))?;
    (uses865(f, finite) == 1 && uses865(f, inner) == 1).then_some((bits, divisor, result))
}

pub(super) fn check_tolerance(module: &naga::Module, f: &naga::Function, b: &ProducerBinding, r: &SourceInstruction) -> Result<bool, String> {
    let lanes = tolerance_lanes(r)?;
    let n = lanes.lanes.len();
    let arity = if lanes.op == ToleranceOp::Div { 2 } else { 1 };
    if !b.controlled
        || b.role != lanes.op.role()
        || b.kind != crate::build::Kind::F
        || b.scalar_bytes != 4
        || b.destination != lanes.destination
        || b.operands.len() != arity
        || b.width.get() as usize != n
        || b.input_widths.iter().any(|w| w.get() as usize != n)
        || b.original_lanes != lanes.lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != (0..n as u8).collect::<Vec<_>>()
    {
        return Ok(false);
    }
    let Some((bits, divisor, _)) = tolerance_graph(f, lanes.op, b.producer.expression) else { return Ok(false) };
    let x = match f.expressions[b.producer.expression] {
        Expression::Math { arg, .. } => arg,
        Expression::Binary { left, .. } => left,
        _ => return Ok(false),
    };
    if b.operands[0].expression != x || divisor.is_some_and(|d| b.operands.get(1).map(|o| o.expression) != Some(d)) {
        return Ok(false);
    }
    let src = &r.instruction.operands[if r.instruction.name() == "sincos" { 2 } else { 1 }];
    let comps: Vec<u8> = lanes.lanes.iter().map(|l| l.1).collect();
    if !register_read865(f, bits, src, &comps, false) {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}

//! Source precise `add_sat` (carrier rule R4). No arithmetic evaluation.
//!
//! Admitted shape: `add_sat [precise] rD, rS, l(c)` with every written lane precise and the
//! immediate equal to a WARP-measured constant (0x3e4ccccd = 0.2, the original VS SHEX1626).
//! Microsoft WARP (fxc `add_sat [precise]`, all 2^32 inputs) returns exactly
//! `saturate(rn(x + 0.2f))` for finite x, 0 for NaN, 1.0 for +Inf, 0 for -Inf and 0.2 for +-0 and
//! +-denormal x. Lowering: `s = x + c` under `AddF32StrictV1` (FPFastMathMode None, an exception to
//! R2), then the exact u32 saturate of `asuint(s)`:
//! `< 0x00800000 -> 0; <= 0x3f800000 -> s; <= 0x7f800000 -> 0x3f800000; else (NaN, negative) -> 0`.
use super::*;
use dxbc_reader::decode::{Register, Selection};

pub const SAT_MEASURED_ADDENDS: [u32; 1] = [0x3e4c_cccd];
pub const SAT_SMALLEST_NORMAL: u32 = 0x0080_0000;
pub const SAT_ONE: u32 = 0x3f80_0000;
pub const SAT_INFINITY: u32 = 0x7f80_0000;

/// (destination lane, src0 component) of an admitted precise `add_sat`.
pub fn add_sat_lanes(r: &SourceInstruction) -> Result<Vec<(u8, u8)>, String> {
    let i = &r.instruction;
    let mut words = vec![0x50050, (r.words.len() + 2) as u32];
    words.extend(&r.words);
    let decoded = dxbc_reader::decode::decode(&words).map_err(|_| "AddSatRawDecodeMismatch")?;
    let mut actual = decoded.instructions.first().ok_or("AddSatRawDecodeMismatch")?.clone();
    actual.word = i.word;
    if decoded.instructions.len() != 1 || format!("{actual:?}") != format!("{i:?}") {
        return Err("AddSatRawDecodeMismatch".into());
    }
    if i.name() != "add" || !i.saturate || i.operands.len() != 3 || r.flags.len() != 1 || r.flags[0] & 1 == 0 || r.reason != PrecisionReason::ExplicitMask {
        return Err("AddSatPolicyUnsupported".into());
    }
    if i.control & !0xf04 != 0
        || !i.extensions.is_empty()
        || i.operands.iter().any(|o| o.modifier != 0 || o.precision != 0 || o.non_uniform || o.indices.iter().any(|x| x.relative.is_some()))
    {
        return Err("AddSatModifierOrControlUnsupported".into());
    }
    let d = &i.operands[0];
    let Selection::Mask(mask) = d.selection else { return Err("AddSatDestinationUnsupported".into()) };
    if mask == 0 || mask & !15 != 0 || d.register != Register::Temp || d.indices.len() != 1 {
        return Err("AddSatDestinationUnsupported".into());
    }
    if i.precise_mask() != mask {
        return Err("AddSatPartialPrecisionUnsupported".into());
    }
    let s = &i.operands[1];
    let c = &i.operands[2];
    if s.register != Register::Temp || s.indices.len() != 1 || s.components != 4 || c.register != Register::Immediate || !c.indices.is_empty() {
        return Err("AddSatInputDomainUnsupported".into());
    }
    let lanes: Vec<u8> = (0..4).filter(|l| mask & (1 << l) != 0).collect();
    if r.destinations.len() != 1 || r.destinations[0].mask != mask || r.destinations[0].lanes != lanes {
        return Err("AddSatDestinationInventoryMismatch".into());
    }
    let pick = |o: &dxbc_reader::decode::Operand, lane: u8| -> Result<u8, String> {
        match o.selection {
            Selection::Scalar(x) if x < 4 => Ok(x),
            Selection::Swizzle(sw) if sw[lane as usize] < 4 => Ok(sw[lane as usize]),
            Selection::Mask(_) if o.register == Register::Immediate => Ok(if o.components == 1 { 0 } else { lane }),
            _ => Err("AddSatSelectionUnsupported".into()),
        }
    };
    lanes
        .iter()
        .map(|&l| {
            let k = pick(c, l)?;
            if !c.immediate.get(k as usize).is_some_and(|v| SAT_MEASURED_ADDENDS.contains(v)) {
                return Err("AddSatAddendNotMeasured".to_string());
            }
            Ok((l, pick(s, l)?))
        })
        .collect()
}

fn lit(f: &naga::Function, h: Handle<Expression>) -> Option<u32> {
    match f.expressions[h] {
        Expression::Literal(naga::Literal::U32(v)) => Some(v),
        Expression::Literal(naga::Literal::F32(v)) => Some(v.to_bits()),
        Expression::Splat { value, .. } => lit(f, value),
        Expression::Compose { ref components, .. } => {
            let v = components.iter().map(|c| lit(f, *c)).collect::<Option<Vec<_>>>()?;
            (!v.is_empty() && v.iter().all(|x| *x == v[0])).then(|| v[0])
        }
        _ => None,
    }
}

/// The admitted graph around the strict add `s`: returns (x, addend, result).
pub fn add_sat_graph(f: &naga::Function, s: Handle<Expression>) -> Option<(Handle<Expression>, Handle<Expression>, Handle<Expression>)> {
    let Expression::Binary { op: naga::BinaryOperator::Add, left: x, right: c } = f.expressions[s] else { return None };
    if !lit(f, c).is_some_and(|v| SAT_MEASURED_ADDENDS.contains(&v)) || uses865(f, s) != 1 {
        return None;
    }
    let (rb, _) = f.expressions.iter().find(|(_, e)| matches!(e, Expression::As { expr, kind: naga::ScalarKind::Uint, convert: None } if *expr == s))?;
    let cmp = |h: Handle<Expression>, op: naga::BinaryOperator, v: u32| matches!(f.expressions[h], Expression::Binary { op: o, left, right } if o == op && left == rb && lit(f, right) == Some(v));
    let (r3, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if cmp(condition, naga::BinaryOperator::LessEqual, SAT_INFINITY) && lit(f, accept) == Some(SAT_ONE) && lit(f, reject) == Some(0)))?;
    let (r2, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if cmp(condition, naga::BinaryOperator::LessEqual, SAT_ONE) && accept == rb && reject == r3))?;
    let (result, _) = f.expressions.iter().find(|(_, e)| matches!(**e, Expression::Select { condition, accept, reject }
        if cmp(condition, naga::BinaryOperator::Less, SAT_SMALLEST_NORMAL) && lit(f, accept) == Some(0) && reject == r2))?;
    (uses865(f, rb) == 4 && uses865(f, r3) == 1 && uses865(f, r2) == 1).then_some((x, c, result))
}

pub(super) fn check_add_sat(module: &naga::Module, f: &naga::Function, b: &ProducerBinding, r: &SourceInstruction) -> Result<bool, String> {
    let lanes = add_sat_lanes(r)?;
    let n = lanes.len();
    if !b.controlled
        || b.role != ProducerRole::SaturateAdd
        || b.kind != crate::build::Kind::F
        || b.destination != 0
        || b.operands.len() != 2
        || b.width.get() as usize != n
        || b.original_lanes != lanes.iter().map(|l| l.0).collect::<Vec<_>>()
        || b.packed_positions != (0..n as u8).collect::<Vec<_>>()
    {
        return Ok(false);
    }
    let Some((x, c, _)) = add_sat_graph(f, b.producer.expression) else { return Ok(false) };
    let comps: Vec<u8> = lanes.iter().map(|l| l.1).collect();
    if b.operands[0].expression != x || b.operands[1].expression != c || !register_read865(f, x, &r.instruction.operands[1], &comps, true) {
        return Ok(false);
    }
    super::transform::check_binding_type(module, f, b)?;
    Ok(true)
}
